-- Property & Casualty question bank for the Wisconsin Property (22-05),
-- Casualty (22-07), and Personal Lines (22-09) exams.
-- GENERATED by supabase/content/build-pc-migration.mjs from
-- supabase/content/pc-questions/*.json. Edit the JSON, then rebuild.
--
-- Every question traces to the PSI outlines (effective July 15, 2022) or to
-- Wisconsin sources cited in docs/WI-OCI-STANDARDS.md (P&C section).
-- Idempotent: skips any question text already present.

insert into public.questions
  (domain, difficulty, question, options, correct, explanation, know_this, state_specific)
select v.domain, v.difficulty, v.question, v.options, v.correct, v.explanation, v.know_this, v.state_specific
from (values
('pc_regulation', 'easy', 'Under ch. 628, Wis. Stat., who must hold a Wisconsin intermediary (producer) license?', '["An adjuster employed only to inspect roofs for the insurer","A policyholder who recommends an agent to a neighbor without compensation","A clerical employee who only files policy paperwork","A person who solicits, negotiates, or places property and casualty insurance for others"]'::jsonb, 'A person who solicits, negotiates, or places property and casualty insurance for others', 'Licensing under ch. 628 applies to anyone who solicits, negotiates, or places insurance on behalf of others. Purely clerical staff who never solicit or negotiate coverage do not need a producer license.', 'Solicit, negotiate, or place = license required.', 'Wisconsin'),
('pc_regulation', 'easy', 'The primary purpose of producer licensing in Wisconsin is to:', '["Raise revenue for the state general fund","Protect the public by ensuring producers are competent and trustworthy","Guarantee insurers a profit on each line","Limit the number of agencies in each county"]'::jsonb, 'Protect the public by ensuring producers are competent and trustworthy', 'Producer licensing is a consumer-protection measure. It screens for competence (prelicensing education and exam) and trustworthiness (background review and discipline).', 'Licensing protects the public, not state revenue.', 'Wisconsin'),
('pc_regulation', 'medium', 'A resident applicant for a Wisconsin property or casualty license must complete how much prelicensing education before testing?', '["10 hours of ethics only","No prelicensing education is required for property or casualty","At least 20 hours: 8 hours of general content plus 12 hours for the line","At least 40 hours of classroom study for each line"]'::jsonb, 'At least 20 hours: 8 hours of general content plus 12 hours for the line', 'OCI requires 20 hours of approved prelicensing education: 8 hours covering principles of insurance, general Wisconsin law, and ethics, plus 12 hours specific to the line of authority. It is valid for one year from completion.', '20 hours = 8 general + 12 line-specific.', 'Wisconsin'),
('pc_regulation', 'medium', 'Wisconsin prelicensing education remains valid for how long after completion?', '["One year","Until the next license renewal cycle","Six months","Two years"]'::jsonb, 'One year', 'OCI states that prelicensing education is valid for one year from the date of completion, so the candidate must pass the exam within that window.', 'Prelicensing certificate is good for 1 year.', 'Wisconsin'),
('pc_regulation', 'easy', 'What score is required to pass a Wisconsin PSI insurance licensing exam?', '["75%","70%","80%","65%"]'::jsonb, '70%', 'The Wisconsin candidate bulletin requires 70% correct to pass each examination.', '70% passes every WI line exam.', 'Wisconsin'),
('pc_regulation', 'easy', 'A licensed Wisconsin producer who changes business addresses must:', '["Retake the licensing exam","Notify only the insurers they are appointed with","Notify the commissioner of the change","Apply for a new license"]'::jsonb, 'Notify the commissioner of the change', 'Licensees must keep their address and contact information current with OCI. A move does not require a new license, but the change must be reported.', 'Address change = report to OCI.', 'Wisconsin'),
('pc_regulation', 'medium', 'Before a Wisconsin agency does business under a name other than the licensee''s legal name, it must:', '["Obtain approval from every appointing insurer","Buy a separate license for each name","Publish the name in a newspaper for 30 days","Register the assumed name with the commissioner"]'::jsonb, 'Register the assumed name with the commissioner', 'Using an assumed (trade) name requires notifying and registering it with OCI so the regulator can connect the name to the responsible licensee.', 'Assumed name must be registered with OCI before use.', 'Wisconsin'),
('pc_regulation', 'hard', 'A Wisconsin producer is disciplined by another state''s insurance regulator. The producer must:', '["Notify only the customers affected in the other state","Report the administrative action to the Wisconsin commissioner","Do nothing unless the other state revoked the license","Wait until the next renewal to disclose it"]'::jsonb, 'Report the administrative action to the Wisconsin commissioner', 'Licensees must report administrative actions taken against them in other jurisdictions to OCI. Waiting for renewal or for a revocation is not permitted.', 'Out-of-state discipline gets reported to OCI.', 'Wisconsin'),
('pc_regulation', 'medium', 'Which action may the commissioner take against a producer after a hearing finds a violation of the insurance laws?', '["Sentence the producer to prison","Cancel the policies the producer sold","Seize the producer''s personal property to pay claims","Suspend or revoke the license and order a monetary forfeiture"]'::jsonb, 'Suspend or revoke the license and order a monetary forfeiture', 'The commissioner''s enforcement powers include license suspension, revocation, or limitation and monetary forfeitures. Criminal penalties are imposed by courts, not by OCI.', 'OCI can suspend/revoke and fine; courts handle criminal cases.', 'Wisconsin'),
('pc_regulation', 'medium', 'Premiums a producer collects on behalf of an insurer are held:', '["As the producer''s income until month-end","By the producer until the policy expires","In the producer''s personal account to earn interest","In a fiduciary capacity and must be promptly remitted"]'::jsonb, 'In a fiduciary capacity and must be promptly remitted', 'Premiums are trust funds. Producers may not commingle them with personal funds and must remit them promptly to the insurer or return them to the insured.', 'Premium = trust money: no commingling, prompt remittance.', 'Wisconsin'),
('pc_regulation', 'medium', 'A producer gives a new homeowners client a $100 gift card that is not specified in the policy as an inducement to buy. This is:', '["Controlled business","Legal if disclosed on the application","Twisting","Rebating, an unfair marketing practice"]'::jsonb, 'Rebating, an unfair marketing practice', 'Giving anything of value not specified in the policy as an inducement to purchase is rebating, which Wisconsin prohibits as an unfair marketing practice under s. 628.34.', 'Anything of value not in the policy to induce a sale = rebating.', 'Wisconsin'),
('pc_regulation', 'medium', 'A producer tells a prospect that a competitor insurer is about to go bankrupt, with no factual basis, to win the account. This is:', '["Defamation of an insurer","Rebating","Sharing commissions","Controlled business"]'::jsonb, 'Defamation of an insurer', 'Making false or maliciously critical statements about another insurer''s financial condition is defamation, a prohibited unfair marketing practice.', 'False statements about a competitor''s finances = defamation.', 'Wisconsin'),
('pc_regulation', 'medium', 'An agent tells a customer that an HO-3 policy covers flood damage to the dwelling. The agent has committed:', '["Boycott","Rebating","Coercion","Misrepresentation"]'::jsonb, 'Misrepresentation', 'Falsely describing the terms or benefits of a policy is misrepresentation. The HO-3 excludes flood; flood coverage generally comes from the NFIP or a private flood policy.', 'Misstating policy benefits = misrepresentation.', 'Wisconsin'),
('pc_regulation', 'hard', 'An agency writes insurance mostly on the property of its own owners, their families, and their employer. Regulators refer to this as:', '["Twisting","Controlled business","Redlining","Churning"]'::jsonb, 'Controlled business', 'Controlled business is insurance written on the producer''s own interests or those of relatives, employers, or affiliated persons. Licensing laws restrict licenses used mainly for controlled business.', 'Selling mainly to yourself and your relatives = controlled business.', 'Wisconsin'),
('pc_regulation', 'medium', 'A Wisconsin producer may share a commission on a property policy with:', '["An unlicensed friend who referred the customer","Any business partner, regardless of licensing","Another appropriately licensed intermediary","The customer who bought the policy"]'::jsonb, 'Another appropriately licensed intermediary', 'Commissions may be shared only with persons licensed for that line. Paying unlicensed persons for placing business, or refunding commission to the buyer, violates the law.', 'Split commissions only with licensed producers.', 'Wisconsin'),
('pc_regulation', 'medium', 'Several insurers agree to refuse to write property coverage for any customer who also buys from a certain agency. This is:', '["Rebating","Reinsurance","Subrogation","Boycott"]'::jsonb, 'Boycott', 'Agreements to refuse to do business with a person (boycott), and threats or pressure to force a purchase (coercion or intimidation), are prohibited unfair practices.', 'Collective refusal to deal = boycott.', 'Wisconsin'),
('pc_regulation', 'medium', 'Which is an unfair claim settlement practice?', '["Not attempting in good faith to settle claims promptly and fairly when liability is reasonably clear","Investigating a claim before paying it","Applying the deductible shown on the declarations","Asking the insured for a proof of loss"]'::jsonb, 'Not attempting in good faith to settle claims promptly and fairly when liability is reasonably clear', 'Unfair claim practices include misrepresenting coverage, failing to acknowledge or investigate claims promptly, and failing to settle in good faith when liability is reasonably clear.', 'Clear liability + no good-faith settlement = unfair claim practice.', 'Wisconsin'),
('pc_regulation', 'medium', 'A certificate of insurance issued to a contractor''s client:', '["Provides evidence of coverage but cannot change or extend the policy''s terms","Amends the policy to add the client as a named insured","Guarantees coverage for any loss, whether excluded or not","Replaces the policy declarations"]'::jsonb, 'Provides evidence of coverage but cannot change or extend the policy''s terms', 'A certificate is informational. It evidences coverage in force but cannot amend, extend, or alter the coverage the policy provides.', 'Certificates evidence coverage; they don''t change it.', 'Wisconsin'),
('pc_regulation', 'easy', 'The Fair Credit Reporting Act mainly regulates:', '["Reinsurance agreements between insurers","Minimum auto liability limits","How premium taxes are calculated","How consumer reports, including credit information, are obtained and used"]'::jsonb, 'How consumer reports, including credit information, are obtained and used', 'The FCRA governs consumer and investigative reports, including notice requirements and the consumer''s rights when adverse action is based on a report.', 'FCRA = rules for using consumer reports.', null),
('pc_regulation', 'medium', 'An insurer raises a personal auto premium based partly on the applicant''s credit-based insurance score. Under the FCRA, the insurer must:', '["Notify the consumer of the adverse action and identify the reporting agency","Refund the difference if the score improves within a year","Get the commissioner''s approval for each such decision","Stop using credit information after the first renewal"]'::jsonb, 'Notify the consumer of the adverse action and identify the reporting agency', 'When an adverse action is based in whole or part on a consumer report, the FCRA requires an adverse action notice identifying the reporting agency and the consumer''s right to a free copy and to dispute errors.', 'Adverse action from a credit report = notice to the consumer.', null),
('pc_regulation', 'hard', 'OCI''s stated position on credit information in personal lines underwriting is that insurers should not:', '["Use credit scores for homeowners but not auto","Tell customers that credit was considered","Use credit information as the sole reason to refuse an application, cancel a new policy in its first 60 days, or nonrenew","Use credit information for any purpose"]'::jsonb, 'Use credit information as the sole reason to refuse an application, cancel a new policy in its first 60 days, or nonrenew', 'OCI''s consumer guidance says insurers may use credit as one criterion but should not use it as the sole reason to refuse, cancel a new policy in its first 60 days, or nonrenew.', 'Credit can be a factor, not the only reason.', 'Wisconsin'),
('pc_regulation', 'hard', 'Under federal law (18 USC 1033), a person with a felony involving dishonesty or breach of trust who wants to work in insurance must:', '["Disclose the conviction only to their employer","Obtain written consent from the appropriate insurance regulator","Work only for a mutual insurer","Wait five years after the conviction"]'::jsonb, 'Obtain written consent from the appropriate insurance regulator', '18 USC 1033 makes it a federal crime for such a person to engage in the business of insurance without written consent from the regulator. Embezzlement and false statements to regulators are also crimes under 1033 and 1034.', 'Prohibited person needs written regulator consent (1033).', null),
('pc_regulation', 'medium', 'The Wisconsin Insurance Security Fund exists to:', '["Insure property owners who are rejected by the voluntary market","Pay covered claims of certain insolvent insurers","Fund the commissioner''s office","Guarantee producers'' commissions"]'::jsonb, 'Pay covered claims of certain insolvent insurers', 'The Wisconsin Insurance Security Fund (ch. 646) is the insolvency backstop that pays covered claims when a member insurer becomes insolvent. The WIP, not the Security Fund, serves hard-to-place property risks.', 'Security Fund = insolvent insurer backstop.', 'Wisconsin'),
('pc_regulation', 'medium', 'Which statement about the commissioner''s examinations of insurers is correct?', '["Insurers may refuse an examination if they are solvent","Only the NAIC may examine a Wisconsin insurer","The commissioner may examine an insurer''s books, records, and affairs","Examinations are limited to foreign insurers"]'::jsonb, 'The commissioner may examine an insurer''s books, records, and affairs', 'The commissioner has broad power to examine insurers'' financial condition and market conduct as part of solvency and consumer-protection regulation.', 'OCI may examine insurers'' records.', 'Wisconsin'),
('pc_regulation', 'medium', 'Wisconsin policies must include a notice advising the insured of:', '["The names of the insurer''s reinsurers","The producer''s commission rate","The right to file a complaint with the Office of the Commissioner of Insurance","The insurer''s loss ratio for the prior year"]'::jsonb, 'The right to file a complaint with the Office of the Commissioner of Insurance', 'Insurers must tell policyholders how to contact OCI to file a complaint. Commission rates and reinsurance arrangements are not required policy notices.', 'Policies carry a notice of the right to complain to OCI.', 'Wisconsin'),
('pc_regulation', 'hard', 'Under Wisconsin law, an insurer that wants to cancel a policy that has been in effect for 60 days or more generally may do so midterm only for reasons such as:', '["A general rate increase across the state","The producer''s appointment being terminated","Any reason stated with 10 days'' notice","Nonpayment of premium, material misrepresentation, or a substantial change in the risk"]'::jsonb, 'Nonpayment of premium, material misrepresentation, or a substantial change in the risk', 's. 631.36(2) limits midterm cancellation to specified grounds, including nonpayment, material misrepresentation, substantial change in the risk, substantial breach of contractual duties, or attainment of a terminal age. Policies in effect less than 60 days are exempt from these limits.', 'After 60 days: cancel only for listed reasons.', 'Wisconsin'),
('pc_regulation', 'medium', 'How much notice must a Wisconsin insurer give before a permitted midterm cancellation takes effect?', '["At least 30 days","At least 10 days after mailing or delivery of the notice","No notice is required for property policies","At least 60 days"]'::jsonb, 'At least 10 days after mailing or delivery of the notice', 's. 631.36(2)(b): no midterm cancellation is effective until at least 10 days after first-class mailing or delivery of the notice to the policyholder.', 'Midterm cancellation = 10 days'' notice.', 'Wisconsin'),
('pc_regulation', 'medium', 'A Wisconsin insurer that decides not to renew a property policy must generally give the policyholder notice at least:', '["30 days after the expiration date","10 days before the expiration date","7 days before the expiration date","60 days before the expiration date"]'::jsonb, '60 days before the expiration date', 's. 631.36(4) requires notice of nonrenewal at least 60 days before expiration, subject to exceptions such as when the insured has obtained replacement coverage or agreed to the nonrenewal.', 'Nonrenewal = 60 days'' notice.', 'Wisconsin'),
('pc_regulation', 'hard', 'When a Wisconsin personal lines property or casualty insurer renews on less favorable terms, notice of the change must generally be given at least:', '["10 days before the renewal date","On the renewal date","90 days before the renewal date","45 days before the renewal date"]'::jsonb, '45 days before the renewal date', 's. 631.36(5) generally requires 60 days'' notice of less favorable renewal terms, but for personal lines property and casualty policies the requirement is at least 45 days.', 'Personal lines: 45 days'' notice of worse renewal terms.', 'Wisconsin'),
('pc_regulation', 'medium', 'Privacy rules on consumer information generally require an insurer to:', '["Publish customer claim files on request","Share medical information with any affiliate without notice","Give customers a notice describing how nonpublic personal information is collected and shared","Destroy all customer records after each renewal"]'::jsonb, 'Give customers a notice describing how nonpublic personal information is collected and shared', 'Privacy laws require notices explaining the insurer''s information practices and limit disclosure of nonpublic personal information to nonaffiliated third parties.', 'Privacy notice explains collection and sharing of personal information.', null),
('pc_regulation', 'medium', 'Under Wisconsin law, what is the effect of a misrepresentation in an application?', '["It bars recovery only if it was made with intent to deceive or it increased the risk or contributed to the loss","It voids the policy no matter how minor","It allows the insurer to double the premium","It never affects coverage once the policy is issued"]'::jsonb, 'It bars recovery only if it was made with intent to deceive or it increased the risk or contributed to the loss', 'Wisconsin''s rule (s. 631.11) is that a misrepresentation or breach of warranty does not defeat recovery unless the insured knew or should have known it was false and it was material to the risk, made with intent to deceive, or it increased the risk or contributed to the loss.', 'Misrepresentation voids coverage only if material or intentional.', 'Wisconsin'),
('pc_regulation', 'hard', 'Under general agency principles in Wisconsin insurance law, knowledge an insurer''s appointed agent gains while acting within the scope of the agency is:', '["Imputed to the insured instead","Imputed to the insurer","Irrelevant to coverage","Binding only if written in the policy"]'::jsonb, 'Imputed to the insurer', 'Knowledge of an agent acting within the scope of authority is treated as knowledge of the principal (the insurer). This is why an agent''s knowledge of a condition can prevent the insurer from later denying coverage over it.', 'Agent''s knowledge = insurer''s knowledge.', 'Wisconsin'),
('pc_regulation', 'medium', 'Many Wisconsin notices and documents may be delivered electronically if:', '["The insurer has more than 1,000 policyholders","The policy is a commercial policy only","The producer signs an affidavit","The policyholder has consented to electronic delivery"]'::jsonb, 'The policyholder has consented to electronic delivery', 'Electronic delivery of notices and documents is permitted when the party has affirmatively consented, and the consumer may withdraw consent.', 'E-delivery requires the customer''s consent.', 'Wisconsin'),
('wi_pc_statutes', 'medium', 'Wisconsin''s general rate standards require that property and casualty rates not be:', '["Based on loss experience","Lower than the prior year''s rates","Excessive, inadequate, or unfairly discriminatory","Different from the national average"]'::jsonb, 'Excessive, inadequate, or unfairly discriminatory', 'The core rate standard (ch. 625) is that rates may not be excessive, inadequate, or unfairly discriminatory. Rates are expected to reflect loss experience.', 'Rates: not excessive, not inadequate, not unfairly discriminatory.', 'Wisconsin'),
('wi_pc_statutes', 'medium', 'Which is a prohibited basis for classifying risks under Wisconsin rating law?', '["Territory, when supported by loss data","Driving record","Construction type of the building","Race, color, creed, or national origin"]'::jsonb, 'Race, color, creed, or national origin', 'Classifying risks based on race, color, creed, or national origin is prohibited. Construction, loss history, driving record, and data-supported territory are legitimate rating factors.', 'No rating by race, color, creed, or national origin.', 'Wisconsin'),
('wi_pc_statutes', 'easy', 'Surplus lines insurance is coverage placed with:', '["The Wisconsin Insurance Security Fund","A state-run insurer","Any insurer by any licensed producer, without restriction","A nonadmitted (unauthorized) insurer through a licensed surplus lines agent"]'::jsonb, 'A nonadmitted (unauthorized) insurer through a licensed surplus lines agent', 'Surplus lines coverage is written by insurers not authorized (admitted) in Wisconsin. It must be placed through a licensed surplus lines agent, generally when coverage is not available from authorized insurers.', 'Surplus lines = nonadmitted insurer + licensed surplus lines agent.', 'Wisconsin'),
('wi_pc_statutes', 'medium', 'Surplus lines placements are generally allowed when:', '["The customer prefers an out-of-state insurer","The producer is not appointed with any admitted insurer","The coverage cannot be obtained from insurers authorized to do business in Wisconsin","The nonadmitted insurer offers a lower premium"]'::jsonb, 'The coverage cannot be obtained from insurers authorized to do business in Wisconsin', 'The surplus lines market is meant for risks the admitted market will not write. A lower price is not by itself a reason to use a nonadmitted insurer.', 'Surplus lines is for risks the admitted market won''t take.', 'Wisconsin'),
('wi_pc_statutes', 'hard', 'A customer''s claim goes unpaid because the surplus lines insurer becomes insolvent. Which statement is most accurate?', '["The Wisconsin Insurance Security Fund pays in full","Surplus lines policies are generally not protected by the state insolvency guaranty fund","The commissioner reimburses the insured from licensing fees","The surplus lines agent must personally pay the claim"]'::jsonb, 'Surplus lines policies are generally not protected by the state insolvency guaranty fund', 'Because surplus lines insurers are nonadmitted, their policyholders generally lack guaranty fund protection. This is one reason surplus lines agents have special disclosure duties.', 'No guaranty fund backstop for surplus lines.', 'Wisconsin'),
('wi_pc_statutes', 'easy', 'A producer with binding authority orally agrees to cover a customer''s new building starting today. This oral binder:', '["Takes effect only after the premium is paid in full","Can create temporary coverage until a written policy is issued","Is void because insurance contracts must be written","Covers only fire losses"]'::jsonb, 'Can create temporary coverage until a written policy is issued', 'Binders, oral or written, provide temporary coverage until the policy is issued or the binder is canceled. Oral contracts of insurance can be enforceable, which is why producers should confirm binders in writing promptly.', 'Oral binders can bind coverage; confirm them in writing.', 'Wisconsin'),
('wi_pc_statutes', 'medium', 'A binder issued by an agent is best described as:', '["A promise to pay the agent''s commission","A temporary agreement providing coverage until the policy is issued","A permanent substitute for the policy","A receipt that provides no coverage"]'::jsonb, 'A temporary agreement providing coverage until the policy is issued', 'A binder provides immediate, temporary coverage on the terms of the policy to be issued and ends when the policy is issued or the binder is canceled.', 'Binder = temporary coverage.', null),
('wi_pc_statutes', 'medium', 'Wisconsin''s risk-sharing plan statute (s. 619.01) allows the commissioner to establish plans when:', '["Premiums rise more than 10% in one year","A producer asks for a new market","An insurer wants to avoid writing a class of business","A type of coverage is not readily available in the voluntary market and the public interest requires it"]'::jsonb, 'A type of coverage is not readily available in the voluntary market and the public interest requires it', 's. 619.01 authorizes mandatory risk-sharing plans (such as the property, auto, and worker''s compensation plans) when coverage is not readily available in the voluntary market.', 'Risk-sharing plans fill voluntary-market gaps.', 'Wisconsin'),
('wi_pc_statutes', 'hard', 'Which statement about participation in Wisconsin''s mandatory risk-sharing plans is most accurate?', '["Insurers writing that type of coverage in Wisconsin generally must participate","Only mutual insurers must participate","Only surplus lines insurers participate","Participation is voluntary for all insurers"]'::jsonb, 'Insurers writing that type of coverage in Wisconsin generally must participate', 'Risk-sharing plans spread the burden among insurers doing business in the state for that line. Participation is generally required as a condition of writing the coverage.', 'Insurers in the line share the residual market.', 'Wisconsin'),
('wi_pc_statutes', 'medium', 'Policy forms used in Wisconsin must meet readability requirements mainly so that:', '["Insurers can reduce printing costs","Consumers can reasonably understand the contract","Courts cannot interpret the policy","Agents can sell faster"]'::jsonb, 'Consumers can reasonably understand the contract', 'Readability standards require plain language and legible formats to improve consumer understanding. Ambiguities in a contract of adhesion are still interpreted against the insurer.', 'Readability rules exist for consumer understanding.', 'Wisconsin'),
('wi_property_regulation', 'medium', 'The Wisconsin Insurance Plan (WIP) provides:', '["Health coverage for uninsurable individuals","Auto liability coverage for high-risk drivers","Worker''s compensation for rejected employers","Basic property insurance for owners unable to buy it in the standard market"]'::jsonb, 'Basic property insurance for owners unable to buy it in the standard market', 'The WIP is a state-mandated, not-for-profit property insurance association that makes basic property coverage available to people who cannot get it in the standard market. WAIP handles auto.', 'WIP = property residual market (Wisconsin''s FAIR plan).', 'Wisconsin'),
('wi_property_regulation', 'medium', 'Losses under Wisconsin Insurance Plan property policies are settled on what basis?', '["Stated amount","Actual cash value","Replacement cost","Agreed value"]'::jsonb, 'Actual cash value', 'The WIP writes dwelling, homeowners, and commercial policies, and all of them settle losses at actual cash value.', 'WIP pays ACV only.', 'Wisconsin'),
('wi_property_regulation', 'hard', 'Which property is generally ineligible for Wisconsin Insurance Plan coverage?', '["An owner-occupied house that meets basic fire standards","A small retail store at a fixed location","A vacant building","A rental duplex that meets loss-prevention standards"]'::jsonb, 'A vacant building', 'The WIP excludes vacant properties, farms, manufacturing properties, and motor vehicles. Eligible property must be at a fixed location and meet basic fire and loss-prevention standards.', 'WIP excludes vacant, farm, and manufacturing risks.', 'Wisconsin'),
('wi_property_regulation', 'medium', 'How does a property owner typically apply to the Wisconsin Insurance Plan?', '["Through a licensed Wisconsin insurance agent","Only through the commissioner''s office","Only after a court order","Through the Department of Revenue"]'::jsonb, 'Through a licensed Wisconsin insurance agent', 'The WIP tells applicants to contact any licensed Wisconsin insurance agent, who can help with the application.', 'Apply to the WIP through any licensed WI agent.', 'Wisconsin'),
('wi_property_regulation', 'hard', 'Which WIP coverage limit is correct?', '["Commercial policies: up to $50,000","Homeowners policies: up to $1,000,000","Dwelling policies: unlimited","Dwelling and homeowners policies: up to $350,000"]'::jsonb, 'Dwelling and homeowners policies: up to $350,000', 'The WIP states maximum limits of $350,000 for dwelling and homeowners policies and $500,000 for commercial policies.', 'WIP maximum: $350K dwelling/HO, $500K commercial.', 'Wisconsin'),
('wi_property_regulation', 'medium', 'Wisconsin law restricts property insurers from refusing, canceling, or charging more for coverage because the applicant is:', '["A victim of domestic abuse","Insuring a frame dwelling","A first-time homebuyer","Located near a fire hydrant"]'::jsonb, 'A victim of domestic abuse', 'Wisconsin limits insurers'' use of an applicant''s or insured''s status as a domestic abuse victim, and also limits use and disclosure of information about domestic abuse. Construction and protection class are legitimate rating factors.', 'Domestic abuse victim status can''t be used against the insured.', 'Wisconsin'),
('wi_property_regulation', 'hard', 'Wisconsin places limits on an insurer''s use and disclosure of information about domestic abuse primarily to:', '["Shift liability to the abuser''s insurer","Require insurers to report all abuse to police","Allow insurers to price domestic abuse risk","Protect victims'' safety and prevent them being penalized for the abuse"]'::jsonb, 'Protect victims'' safety and prevent them being penalized for the abuse', 'The restrictions protect victims, for example by preventing disclosure of a victim''s location or claim information to the abuser, and by barring adverse underwriting because of abuse status.', 'Protect victims: limit use and disclosure.', 'Wisconsin'),
('wi_property_regulation', 'medium', 'A mortgage lender requires property insurance on a financed home. The borrower generally:', '["May choose the insurer and agent, as long as the coverage meets the lender''s reasonable requirements","Must accept whatever policy the lender selects","Must buy from the lender''s affiliated agency","Cannot name the lender on the policy"]'::jsonb, 'May choose the insurer and agent, as long as the coverage meets the lender''s reasonable requirements', 'Lenders may require adequate coverage and to be named as mortgagee, but tying the loan to a particular insurer or agent is prohibited coercion.', 'Lender can require coverage, not a specific insurer.', 'Wisconsin'),
('wi_property_regulation', 'easy', 'Which party is protected by the standard mortgage clause in a property policy?', '["The insured''s auto insurer","The producer","The insured''s neighbor","The mortgage lender"]'::jsonb, 'The mortgage lender', 'The standard mortgage clause protects the lender''s interest, including payment rights even if the insured''s own coverage is voided by the insured''s acts, provided the lender meets its obligations.', 'Mortgage clause protects the lender.', null),
('wi_property_regulation', 'hard', 'Under a standard mortgage clause, if the insurer denies the homeowner''s fire claim because the homeowner committed arson, the insurer generally:', '["Still pays the mortgagee up to its interest","Pays the homeowner''s family","Pays nothing to anyone","Cancels the mortgage"]'::jsonb, 'Still pays the mortgagee up to its interest', 'The mortgage clause creates a separate agreement with the lender. The lender''s recovery is not defeated by the insured''s wrongful acts, and the insurer may then be subrogated to the lender''s rights.', 'Insured''s misconduct doesn''t defeat the mortgagee.', null),
('wi_auto_regulation', 'easy', 'Wisconsin''s minimum auto liability limits are:', '["$50,000 / $100,000 / $25,000","$100,000 combined single limit","$25,000 per person / $50,000 per accident bodily injury and $10,000 property damage","$15,000 / $30,000 / $5,000"]'::jsonb, '$25,000 per person / $50,000 per accident bodily injury and $10,000 property damage', 'OCI lists Wisconsin''s minimum liability limits as $25,000 for injury or death of one person, $50,000 for two or more, and $10,000 property damage (25/50/10).', 'WI minimum liability: 25/50/10.', 'Wisconsin'),
('wi_auto_regulation', 'medium', 'Uninsured motorist coverage in Wisconsin is:', '["Required for property damage only","Optional and must be requested in writing","Required, with at least $25,000/$50,000 for bodily injury","Required only for commercial vehicles"]'::jsonb, 'Required, with at least $25,000/$50,000 for bodily injury', 'Wisconsin requires uninsured motorist coverage of at least $25,000 per person and $50,000 per accident, bodily injury only. It also applies to hit-and-run drivers.', 'UM is mandatory in WI: 25/50, bodily injury only.', 'Wisconsin'),
('wi_auto_regulation', 'medium', 'Which statement about underinsured motorist (UIM) coverage in Wisconsin is correct?', '["It is mandatory at 25/50","It is prohibited in Wisconsin","It is included automatically in liability coverage","It is not mandatory, but insurers must notify the insured it is available"]'::jsonb, 'It is not mandatory, but insurers must notify the insured it is available', 'UIM is optional in Wisconsin. The insurer must notify the policyholder of its availability when the policy is delivered. If purchased, OCI lists minimum limits of $50,000 per person and $100,000 per accident.', 'UIM: optional, but must be offered.', 'Wisconsin'),
('wi_auto_regulation', 'hard', 'If a Wisconsin driver buys underinsured motorist coverage, the minimum limits are:', '["$100,000 / $300,000","$25,000 / $50,000","$50,000 per person / $100,000 per accident","$10,000 / $20,000"]'::jsonb, '$50,000 per person / $100,000 per accident', 'OCI''s auto guide: if purchased, UIM minimum limits are $50,000 per person and $100,000 per accident.', 'UIM minimum if bought: 50/100.', 'Wisconsin'),
('wi_auto_regulation', 'medium', 'Uninsured motorist coverage responds when an insured is injured by:', '["A hit-and-run driver or a driver with no liability insurance","The insured''s own negligence","A driver whose liability limits are lower than the insured''s damages","A vehicle owned by the insured"]'::jsonb, 'A hit-and-run driver or a driver with no liability insurance', 'UM covers bodily injury caused by an uninsured or hit-and-run motorist. A driver with coverage that is too low triggers underinsured motorist coverage instead.', 'UM = no insurance or hit-and-run. UIM = not enough insurance.', 'Wisconsin'),
('wi_auto_regulation', 'medium', 'Under Wisconsin''s financial responsibility law, a driver in an accident causing injury, death, or property damage over $1,000 must:', '["Notify only their insurer","File a Driver''s Report of Accident with DMV within 10 days","Pay all damages within 30 days","Surrender their license immediately"]'::jsonb, 'File a Driver''s Report of Accident with DMV within 10 days', 'OCI''s auto guide: after an accident with injury, death, or property damage over $1,000, the driver must file a Driver''s Report of Accident with DMV within 10 days. Uninsured at-fault drivers face license and registration suspension.', 'Accident report to DMV within 10 days.', 'Wisconsin'),
('wi_auto_regulation', 'medium', 'An uninsured Wisconsin driver causes an accident and does not pay the resulting damages. Under the financial responsibility law, the driver may face:', '["Automatic assignment to a new insurer","Suspension of driving privileges and vehicle registration","Federal prosecution","A lifetime driving ban"]'::jsonb, 'Suspension of driving privileges and vehicle registration', 'The financial responsibility law uses license and registration suspension to push at-fault uninsured drivers to pay damages or post security.', 'Uninsured + unpaid damages = license and registration suspension.', 'Wisconsin'),
('wi_auto_regulation', 'medium', 'The Wisconsin Automobile Insurance Plan (WAIP) exists to:', '["Replace uninsured motorist coverage","Provide auto insurance for drivers who cannot get it in the voluntary market","Regulate car dealers","Insure state-owned vehicles"]'::jsonb, 'Provide auto insurance for drivers who cannot get it in the voluntary market', 'WAIP is a plan created by Wisconsin law to provide auto insurance to those who cannot secure coverage from usual market sources. Policies are issued by assigned insurers.', 'WAIP = auto residual market.', 'Wisconsin'),
('wi_auto_regulation', 'hard', 'Compared with the voluntary market, WAIP premiums are typically:', '["Much lower, because they are subsidized","Somewhat higher","Set by each assigned agent","Identical by law"]'::jsonb, 'Somewhat higher', 'OCI notes that WAIP-assigned insurers charge rates somewhat higher than rates in the voluntary market, reflecting the higher-risk pool.', 'WAIP rates run higher than the voluntary market.', 'Wisconsin'),
('wi_auto_regulation', 'medium', 'A new Wisconsin auto policy has been in force for 30 days. The insurer may cancel it:', '["Never, until the first renewal","Only with 60 days'' notice","For any lawful reason, with at least 10 days'' written notice","Only for nonpayment of premium"]'::jsonb, 'For any lawful reason, with at least 10 days'' written notice', 'OCI''s guide notes insurers may cancel a new policy within the first 59 days with at least 10 days'' written notice. After that, midterm cancellation is limited to specific reasons.', 'First 59 days: cancel for any lawful reason with 10 days'' notice.', 'Wisconsin'),
('wi_auto_regulation', 'hard', 'Wisconsin law may hold which adult liable for a minor''s negligent driving?', '["Any adult living in the same county","The adult who signed (sponsored) the minor''s driver''s license application","The minor''s driving instructor","The owner of the road where the accident occurred"]'::jsonb, 'The adult who signed (sponsored) the minor''s driver''s license application', 'Wisconsin addresses responsibility for minors operating motor vehicles by imputing liability to the adult sponsor who signed the minor''s license application.', 'Minor''s license sponsor can be liable for the minor''s driving.', 'Wisconsin'),
('wi_auto_regulation', 'medium', 'Medical payments coverage on a Wisconsin auto policy:', '["Is required at $10,000","Is optional; if purchased, the minimum limit is $1,000","Pays only the other driver''s medical bills","Is prohibited"]'::jsonb, 'Is optional; if purchased, the minimum limit is $1,000', 'OCI lists medical payments as optional coverage that pays medical or funeral expenses for occupants of the insured auto, with a minimum purchasable limit of $1,000.', 'Med pay: optional, $1,000 minimum if bought.', 'Wisconsin'),
('pc_general_insurance', 'easy', 'A peril is best defined as:', '["The cause of a loss, such as fire or windstorm","The uncertainty of loss","A condition that increases the chance of loss","The amount the insured must pay before coverage applies"]'::jsonb, 'The cause of a loss, such as fire or windstorm', 'A peril is the cause of loss. A hazard increases the likelihood or severity of loss, and risk is the uncertainty of loss.', 'Peril = cause. Hazard = condition that increases it.', null),
('pc_general_insurance', 'easy', 'Oily rags stored next to a furnace are an example of a:', '["Moral hazard","Physical hazard","Peril","Morale hazard"]'::jsonb, 'Physical hazard', 'A physical hazard is a tangible condition that increases the chance of loss. Moral hazard involves dishonesty, and morale hazard involves carelessness or indifference because insurance exists.', 'Tangible condition = physical hazard.', null),
('pc_general_insurance', 'medium', 'An insured stops locking the garage because "insurance will cover it anyway." This is a:', '["Moral hazard","Speculative risk","Physical hazard","Morale hazard"]'::jsonb, 'Morale hazard', 'Morale hazard is indifference to loss because insurance exists. Moral hazard is dishonesty, such as intentionally causing or inflating a loss.', 'Careless because insured = morale hazard.', null),
('pc_general_insurance', 'medium', 'Installing a sprinkler system in a warehouse is an example of which risk management method?', '["Retention","Avoidance","Transfer","Reduction"]'::jsonb, 'Reduction', 'Reduction lowers the frequency or severity of loss. Avoidance eliminates the activity, transfer shifts the financial consequences (such as buying insurance), and retention keeps the risk.', 'Sprinklers, alarms, safety programs = risk reduction.', null),
('pc_general_insurance', 'medium', 'Which risk is generally insurable?', '["Loss from normal wear and tear","Pure risk, where the only outcomes are loss or no loss","Speculative risk, such as investing in stocks","Gambling losses"]'::jsonb, 'Pure risk, where the only outcomes are loss or no loss', 'Insurance covers pure risks. Speculative risks carry a chance of gain, and wear and tear is certain rather than accidental.', 'Only pure risk is insurable.', null),
('pc_general_insurance', 'medium', 'Adverse selection occurs when:', '["People with a higher-than-average chance of loss seek insurance more than others","An insurer rejects all high-risk applicants","Losses are spread across a large group","An insurer buys reinsurance"]'::jsonb, 'People with a higher-than-average chance of loss seek insurance more than others', 'Adverse selection is the tendency of higher-risk people to seek or keep coverage. Underwriting exists largely to control it.', 'Adverse selection = higher risks buying more insurance.', null),
('pc_general_insurance', 'medium', 'The law of large numbers helps insurers because:', '["Larger claims are always paid faster","Predicted losses become more accurate as the number of similar exposures grows","Insurers can charge more to large groups","It eliminates catastrophic losses"]'::jsonb, 'Predicted losses become more accurate as the number of similar exposures grows', 'With more similar, independent exposures, actual results come closer to expected results, which makes premiums more predictable.', 'More exposures = more accurate predictions.', null),
('pc_general_insurance', 'medium', 'An insurer that transfers part of its risk to another insurer is using:', '["Subrogation","Coinsurance","Reinsurance","Self-insurance"]'::jsonb, 'Reinsurance', 'Reinsurance is insurance for insurers. The ceding insurer transfers part of its exposure to a reinsurer to protect solvency and increase capacity.', 'Insurer''s insurance = reinsurance.', null),
('pc_general_insurance', 'medium', 'A reciprocal insurance exchange is:', '["A government insurance program","A company owned by stockholders","A group of subscribers who insure one another, managed by an attorney-in-fact","A fraternal organization with a lodge system"]'::jsonb, 'A group of subscribers who insure one another, managed by an attorney-in-fact', 'In a reciprocal, subscribers exchange risks among themselves, and an attorney-in-fact manages the exchange.', 'Reciprocal = subscribers + attorney-in-fact.', null),
('pc_general_insurance', 'medium', 'An insurer incorporated in Illinois and doing business in Wisconsin is, from Wisconsin''s point of view, a:', '["Foreign insurer","Alien insurer","Domestic insurer","Nonadmitted insurer by definition"]'::jsonb, 'Foreign insurer', 'Domestic insurers are formed in the state, foreign insurers in another U.S. state, and alien insurers outside the U.S. Admitted status is a separate question of authorization.', 'Other U.S. state = foreign. Other country = alien.', null),
('pc_general_insurance', 'medium', 'An agent tells a customer she can bind coverage because the agent routinely binds similar risks and the insurer has never objected. This authority is:', '["No authority","Implied authority","Apparent authority","Express authority"]'::jsonb, 'Implied authority', 'Express authority is written in the agency contract. Implied authority is what is reasonably needed to carry out express authority or follows from custom. Apparent authority arises from what the public reasonably believes because of the insurer''s conduct.', 'Express = written. Implied = customary/necessary. Apparent = public perception.', null),
('pc_general_insurance', 'medium', 'Because the insured pays a small premium for the chance of a much larger recovery, an insurance contract is:', '["Conditional","Personal","Aleatory","Unilateral"]'::jsonb, 'Aleatory', 'An aleatory contract involves an unequal exchange of values that depends on an uncertain event.', 'Unequal exchange = aleatory.', null),
('pc_general_insurance', 'medium', 'Because the insurer drafts the policy and the insured must accept it as written, courts interpret ambiguities:', '["In favor of the insured","In favor of the insurer","By splitting the difference","By asking the commissioner to decide"]'::jsonb, 'In favor of the insured', 'Insurance policies are contracts of adhesion, so ambiguous language is construed against the drafter, the insurer.', 'Contract of adhesion: ambiguity favors the insured.', null),
('pc_general_insurance', 'medium', 'The principle of indemnity means that the insured:', '["Always receives replacement cost","Is paid the policy limit for any covered loss","Should be restored to the same financial position as before the loss, not profit from it","May collect from every policy covering the loss"]'::jsonb, 'Should be restored to the same financial position as before the loss, not profit from it', 'Indemnity limits recovery to the actual loss. Other insurance clauses, subrogation, and actual cash value settlements all support this principle.', 'Indemnity = make whole, no profit.', null),
('property_basics', 'easy', 'To collect on a property policy, an insured must have an insurable interest:', '["At the time of the loss","At both application and 10 years after the loss","Never; it applies only to life insurance","Only when the policy is applied for"]'::jsonb, 'At the time of the loss', 'In property insurance, insurable interest must exist at the time of the loss. In life insurance, it must exist at the time of application.', 'Property: insurable interest at time of loss.', null),
('property_basics', 'easy', 'Actual cash value is most commonly calculated as:', '["The amount stated on the application","Replacement cost minus depreciation","The original purchase price","Replacement cost plus inflation"]'::jsonb, 'Replacement cost minus depreciation', 'Actual cash value is usually replacement cost at the time of loss minus physical depreciation. Some courts use fair market value or the broad evidence rule.', 'ACV = replacement cost − depreciation.', null),
('property_basics', 'medium', 'A 10-year-old roof with a 20-year expected life is destroyed. Replacement cost is $12,000. What is the actual cash value?', '["$4,000","$12,000","$6,000","$9,000"]'::jsonb, '$6,000', 'Depreciation is 10/20 = 50%. ACV = $12,000 − $6,000 = $6,000.', 'ACV = RC × (remaining life ÷ total life).', null),
('property_basics', 'medium', 'Which valuation method pays to repair or replace with materials of like kind and quality without deducting depreciation?', '["Actual cash value","Replacement cost","Functional replacement cost","Market value"]'::jsonb, 'Replacement cost', 'Replacement cost pays the current cost to repair or replace with like kind and quality, without depreciation. Functional replacement cost uses modern, less expensive materials that perform the same function.', 'Replacement cost = no depreciation deduction.', null),
('property_basics', 'medium', 'An older home has ornate plaster walls. The policy pays to replace them with drywall that serves the same purpose. This valuation is:', '["Stated amount","Actual cash value","Agreed value","Functional replacement cost"]'::jsonb, 'Functional replacement cost', 'Functional replacement cost uses modern, less expensive materials that are functionally equivalent. It is common for older homes whose market value is well below reproduction cost.', 'Functionally equivalent, cheaper materials = functional replacement cost.', null),
('property_basics', 'medium', 'A fine art collector and insurer agree in advance that a painting is worth $80,000, and that amount will be paid for a total loss. This is:', '["Market value","Replacement cost","Actual cash value","Agreed value"]'::jsonb, 'Agreed value', 'Agreed value is set when the policy is written and paid in full for a total loss, without depreciation. It is common for art and collectibles.', 'Value fixed in advance = agreed value.', null),
('property_basics', 'hard', 'A "stated amount" policy on a classic car differs from an agreed value policy because it pays:', '["The lesser of the stated amount, ACV, or cost to repair or replace","Only for partial losses","The stated amount in every total loss","More than the stated amount if values rise"]'::jsonb, 'The lesser of the stated amount, ACV, or cost to repair or replace', 'A stated amount is a maximum, not a guarantee. The insurer pays the lesser of the stated amount, actual cash value, or repair or replacement cost.', 'Stated amount = a ceiling, not a promise.', null),
('property_basics', 'medium', 'Named perils coverage differs from special (open perils) coverage because named perils coverage:', '["Requires the insurer to prove an exclusion applies","Covers only liability losses","Covers all losses unless specifically excluded","Covers only losses caused by perils specifically listed"]'::jsonb, 'Covers only losses caused by perils specifically listed', 'Named perils covers only listed perils, and the insured must show a listed peril caused the loss. Special (open perils) covers direct physical loss unless excluded, and the insurer must show an exclusion applies.', 'Named = listed only. Open = all except excluded.', null),
('property_basics', 'medium', 'After a fire, a restaurant loses income while closed for repairs. This lost income is a:', '["Moral hazard loss","Direct loss","Consequential (indirect) loss","Liability loss"]'::jsonb, 'Consequential (indirect) loss', 'A direct loss is physical damage to property. Lost income, extra expense, and spoilage that result from that damage are consequential or indirect losses.', 'Lost income after damage = indirect loss.', null),
('property_basics', 'medium', 'One limit that applies to several buildings or locations together is called:', '["Specific insurance","Excess insurance","Blanket insurance","Scheduled insurance"]'::jsonb, 'Blanket insurance', 'Blanket insurance applies one limit across multiple items or locations. Specific insurance assigns a separate limit to each item or location.', 'One limit over many items = blanket.', null),
('property_basics', 'medium', 'Which construction type is generally the most fire-resistive?', '["Non-combustible (unprotected steel)","Fire-resistive (masonry/concrete with protected steel)","Frame","Joisted masonry"]'::jsonb, 'Fire-resistive (masonry/concrete with protected steel)', 'Fire-resistive construction has the best fire rating. Frame is the most combustible, and unprotected steel can weaken in high heat.', 'Frame is worst; fire-resistive is best.', null),
('property_basics', 'medium', 'A building''s value is $400,000 and the policy has an 80% coinsurance clause. What is the minimum amount of insurance required to avoid a coinsurance penalty?', '["$320,000","$400,000","$280,000","$300,000"]'::jsonb, '$320,000', 'Required insurance = value × coinsurance percentage = $400,000 × 80% = $320,000.', 'Required = value × coinsurance %.', null),
('property_basics', 'hard', 'A building worth $500,000 is insured for $300,000 with an 80% coinsurance clause. A $100,000 loss occurs and there is no deductible. What does the insurer pay?', '["$80,000","$100,000","$60,000","$75,000"]'::jsonb, '$75,000', 'Required = $500,000 × 80% = $400,000. Did/should = $300,000 ÷ $400,000 = 0.75. $100,000 × 0.75 = $75,000.', '(Did ÷ Should) × Loss.', null),
('property_basics', 'hard', 'A building worth $200,000 is insured for $160,000 with an 80% coinsurance clause and a $1,000 deductible. A $50,000 loss occurs. What does the insurer pay?', '["$50,000","$49,000","$40,000","$39,000"]'::jsonb, '$49,000', 'Required = $200,000 × 80% = $160,000, so the insured met coinsurance. Payment = $50,000 − $1,000 deductible = $49,000.', 'Coinsurance met = loss − deductible.', null),
('property_basics', 'medium', 'A coinsurance penalty applies when:', '["The loss is a total loss","The insured has two policies","The insured files more than one claim a year","The insured carries less than the required percentage of value at the time of loss"]'::jsonb, 'The insured carries less than the required percentage of value at the time of loss', 'Coinsurance is measured at the time of loss. If the limit is below the required percentage of value, partial losses are paid proportionally. Payment never exceeds the limit.', 'Underinsured at time of loss = penalty.', null),
('property_basics', 'medium', 'Two policies cover the same building: Insurer A for $60,000 and Insurer B for $40,000. Under a pro rata other-insurance clause, how much does A pay on a $20,000 loss?', '["$10,000","$8,000","$12,000","$20,000"]'::jsonb, '$12,000', 'A''s share = $60,000 ÷ $100,000 = 60%. 60% × $20,000 = $12,000.', 'Pro rata = each pays its share of total limits.', null),
('property_basics', 'hard', 'Under contribution by equal shares, two insurers with limits of $50,000 and $200,000 cover a $150,000 loss. How much does each pay?', '["$30,000 and $120,000","$150,000 from the second only","$75,000 each","$50,000 from the first and $100,000 from the second"]'::jsonb, '$50,000 from the first and $100,000 from the second', 'Each pays equally until the smaller limit is used up: $50,000 each ($100,000). The remaining $50,000 comes from the second insurer, for $100,000 total from it.', 'Equal shares until the smaller limit runs out.', null),
('property_basics', 'medium', 'After paying a claim, the insurer takes over the insured''s right to recover from the party who caused the loss. This is:', '["Liberalization","Abandonment","Salvage","Subrogation"]'::jsonb, 'Subrogation', 'Subrogation transfers the insured''s recovery rights against a responsible third party to the insurer, to the extent the insurer paid. It prevents the insured from collecting twice.', 'Insurer steps into insured''s shoes = subrogation.', null),
('property_basics', 'medium', 'An insurer pays a total loss on a stolen motorcycle, then the motorcycle is recovered. Taking and selling the motorcycle is the insurer''s right of:', '["Subrogation","Salvage","Abandonment","Assignment"]'::jsonb, 'Salvage', 'Salvage is damaged or recovered property the insurer takes after paying the claim. The abandonment clause says the insured cannot simply abandon property to the insurer without its agreement.', 'Insurer keeps recovered or damaged property = salvage.', null),
('property_basics', 'medium', 'The abandonment provision in a property policy means:', '["The insured may abandon the policy at any time without notice","The insured cannot abandon damaged property to the insurer and demand full payment","Vacant property is automatically abandoned","The insurer may abandon the insured after a claim"]'::jsonb, 'The insured cannot abandon damaged property to the insurer and demand full payment', 'The insurer need not accept property the insured abandons. The insurer decides whether to take salvage.', 'You can''t dump damaged property on the insurer.', null),
('property_basics', 'medium', 'The liberalization clause provides that:', '["If the insurer broadens a form without extra premium, the broader coverage applies automatically to existing policies","The insured may add coverage without paying","The insurer may reduce coverage at any time","Claims will be paid faster after a catastrophe"]'::jsonb, 'If the insurer broadens a form without extra premium, the broader coverage applies automatically to existing policies', 'Under liberalization, broadened coverage adopted without extra premium during the policy term (or a set period before it) automatically applies to existing policies.', 'Free broadening applies automatically.', null),
('property_basics', 'medium', 'Which part of a property policy lists the named insured, address, limits, premium, and policy period?', '["Conditions","Declarations","Insuring agreement","Exclusions"]'::jsonb, 'Declarations', 'The declarations page summarizes the who, what, where, when, and how much of the policy.', 'Declarations = policy summary page.', null),
('property_basics', 'easy', 'Which part of a policy states the insurer''s promise to pay?', '["Declarations","Insuring agreement","Conditions","Definitions"]'::jsonb, 'Insuring agreement', 'The insuring agreement states what the insurer promises to cover. Conditions state the duties of both parties, and exclusions remove coverage.', 'The promise to pay = insuring agreement.', null),
('property_basics', 'medium', 'When a policy has several named insureds, cancellation requests and premium payments are usually the responsibility of the:', '["Mortgagee","Last named insured","First named insured","Producer"]'::jsonb, 'First named insured', 'The first named insured, listed first on the declarations, is responsible for premium payments and receiving return premiums, and is the party that may request cancellation.', 'First named insured handles premium and cancellation.', null),
('property_basics', 'medium', 'After a covered loss, a property policy''s "duties after loss" condition requires the insured to:', '["Wait 30 days before reporting the loss","Give prompt notice, protect the property from further damage, and provide a proof of loss if asked","Admit liability to any third party","Repair the property before the adjuster inspects"]'::jsonb, 'Give prompt notice, protect the property from further damage, and provide a proof of loss if asked', 'Typical duties include prompt notice, protecting property from further damage, keeping records, showing the damaged property, and giving a signed, sworn proof of loss if requested.', 'Notify, protect, document, prove.', null),
('property_basics', 'medium', 'A loss payable clause is most commonly used to protect:', '["A contractor working on the building","A neighbor injured on the premises","A lender with an interest in personal property, such as a financed car or equipment","The insured''s spouse"]'::jsonb, 'A lender with an interest in personal property, such as a financed car or equipment', 'The loss payable clause adds a secured creditor on personal property as a payee. The standard mortgage clause is used for real property.', 'Loss payable = lender on personal property.', null),
('property_basics', 'hard', 'The "no benefit to bailee" provision means:', '["The insured cannot recover for property left with others","The insurer will not subrogate against a bailee","A bailee''s customers are automatically covered","A party holding the insured''s property for a fee cannot benefit from the insured''s coverage"]'::jsonb, 'A party holding the insured''s property for a fee cannot benefit from the insured''s coverage', 'No benefit to bailee prevents a bailee, such as a dry cleaner or repair shop, from avoiding responsibility by relying on the owner''s insurance. This preserves the insurer''s subrogation rights.', 'Bailee can''t use the owner''s insurance to escape liability.', null),
('property_basics', 'medium', 'A loss ratio is calculated as:', '["Claims count divided by policy count","Expenses divided by written premium","Losses (incurred losses and loss adjustment expense) divided by earned premium","Earned premium divided by losses"]'::jsonb, 'Losses (incurred losses and loss adjustment expense) divided by earned premium', 'The loss ratio compares losses to premiums. A high loss ratio signals rates may be inadequate or underwriting too loose.', 'Loss ratio = losses ÷ premiums.', null),
('dwelling', 'easy', 'The dwelling policy (DP) program is most often used to insure:', '["Automobiles","Owner-occupied or rental dwellings that are not eligible for, or do not need, a homeowners policy","Commercial office buildings","Farm machinery"]'::jsonb, 'Owner-occupied or rental dwellings that are not eligible for, or do not need, a homeowners policy', 'Dwelling forms cover residential structures of one to four units, including rentals, seasonal homes, and homes that do not qualify for homeowners coverage.', 'DP = dwellings, including rentals.', null),
('dwelling', 'easy', 'The DP-1 (Basic Form) covers which perils without optional endorsements?', '["Theft and vandalism only","Flood and earthquake","Fire, lightning, and internal explosion","All risks of direct physical loss"]'::jsonb, 'Fire, lightning, and internal explosion', 'The DP-1 covers fire, lightning, and internal explosion. Extended coverage perils and vandalism or malicious mischief can be added for an additional premium.', 'DP-1 = fire, lightning, internal explosion.', null),
('dwelling', 'medium', 'Which dwelling form covers the dwelling and other structures on an open perils (special) basis?', '["DP-1","DP-3","All three forms","DP-2"]'::jsonb, 'DP-3', 'The DP-3 covers Coverages A and B against open perils and personal property against broad named perils. The DP-2 is broad named perils and the DP-1 is basic named perils.', 'DP-3 = special on the building.', null),
('dwelling', 'medium', 'In the dwelling policy, Coverage D provides:', '["Personal liability","Additional living expense","Fair rental value","Medical payments"]'::jsonb, 'Fair rental value', 'Dwelling Coverage D is fair rental value (lost rent). Coverage E is additional living expense. Liability requires the personal liability supplement.', 'DP Cov D = fair rental value; Cov E = ALE.', null),
('dwelling', 'medium', 'Which dwelling coverage is NOT included in the DP-1 basic form?', '["Coverage C – Personal property","Coverage D – Fair rental value","Coverage E – Additional living expense","Coverage A – Dwelling"]'::jsonb, 'Coverage E – Additional living expense', 'The DP-1 includes Coverages A, B, C, and D. Additional living expense (Coverage E) is included in the DP-2 and DP-3.', 'No ALE in the DP-1.', null),
('dwelling', 'medium', 'How does a landlord insured under a dwelling policy get coverage for tenants'' injuries caused by the landlord''s negligence?', '["Liability coverage is not available for rentals","Buy a DP-3 instead of a DP-1","Add a personal liability supplement","It is automatically included in Coverage A"]'::jsonb, 'Add a personal liability supplement', 'Dwelling forms are property-only. The personal liability supplement adds personal liability and medical payments to others.', 'DP liability comes from the personal liability supplement.', null),
('dwelling', 'medium', 'Under the dwelling forms, other structures coverage is provided as an additional amount equal to what percentage of the Coverage A limit?', '["5%","20%","50%","10%"]'::jsonb, '10%', 'The dwelling forms let the insured use up to 10% of the Coverage A limit for other structures, in addition to Coverage A.', 'Other structures = 10% of A.', null),
('dwelling', 'hard', 'Which endorsement adds theft coverage to a dwelling policy?', '["Dwelling under construction (DP 11 43)","Broad theft coverage (DP 04 72)","Special provisions (DP 01 43)","Automatic increase in insurance (DP 04 11)"]'::jsonb, 'Broad theft coverage (DP 04 72)', 'Standard dwelling forms do not cover theft of personal property. The broad theft coverage endorsement (DP 04 72) adds it for owner-occupied dwellings.', 'DP theft = DP 04 72.', null),
('dwelling', 'medium', 'The automatic increase in insurance endorsement (DP 04 11) is used to:', '["Add replacement cost to personal property","Increase the deductible each year","Automatically double limits after a loss","Increase Coverage A by an annual percentage to keep up with rising construction costs"]'::jsonb, 'Increase Coverage A by an annual percentage to keep up with rising construction costs', 'The automatic increase endorsement raises the Coverage A limit gradually during the policy term by a selected annual percentage.', 'DP 04 11 = inflation guard.', null),
('dwelling', 'medium', 'Which endorsement is used when a dwelling is being built?', '["Dwelling under construction (DP 11 43)","Broad theft coverage (DP 04 72)","Scheduled personal property (HO 04 61)","Builders risk (CP 00 20)"]'::jsonb, 'Dwelling under construction (DP 11 43)', 'The dwelling under construction endorsement adjusts the limit to reflect the increasing value of a residence under construction.', 'Building a house on a DP = DP 11 43.', null),
('dwelling', 'medium', 'Under the dwelling policy, an insured dwelling that has been vacant for more than 60 consecutive days generally loses coverage for:', '["Lightning","Fire","Windstorm","Vandalism and malicious mischief"]'::jsonb, 'Vandalism and malicious mischief', 'Vandalism, malicious mischief, and glass breakage are excluded once a building has been vacant more than 60 consecutive days. Fire and lightning coverage continues.', 'Vacant 60+ days = no vandalism coverage.', null),
('dwelling', 'medium', 'Which peril is a general exclusion in the dwelling forms?', '["Internal explosion","Flood (water damage from surface water)","Lightning","Fire"]'::jsonb, 'Flood (water damage from surface water)', 'General exclusions include flood and surface water, earth movement, ordinance or law, war, nuclear hazard, neglect, and intentional loss.', 'Flood and earth movement are excluded.', null),
('dwelling', 'hard', 'Which dwelling form covers personal property against broad named perils rather than basic perils?', '["The DP-1 only","The DP-2 and the DP-3","None; personal property is excluded","The DP-3 only, on an open perils basis"]'::jsonb, 'The DP-2 and the DP-3', 'The DP-2 covers the building and contents on a broad named perils basis. The DP-3 covers the building on an open perils basis and contents on a broad named perils basis.', 'DP-2 and DP-3 contents = broad named perils.', null),
('dwelling', 'medium', 'A dwelling policy loss settlement on the dwelling is on a replacement cost basis under which forms?', '["DP-1 only","All three forms","None of the forms","DP-2 and DP-3"]'::jsonb, 'DP-2 and DP-3', 'The DP-1 settles at actual cash value. The DP-2 and DP-3 use replacement cost for the dwelling and other structures when insurance-to-value requirements are met.', 'DP-1 = ACV. DP-2/3 buildings = RC.', null),
('homeowners', 'easy', 'Which homeowners form is designed for renters?', '["HO-4","HO-8","HO-3","HO-6"]'::jsonb, 'HO-4', 'The HO-4 (Contents Broad Form) covers a tenant''s personal property, loss of use, and liability. It has no dwelling coverage.', 'HO-4 = renters.', null),
('homeowners', 'easy', 'Which homeowners form is designed for condominium unit owners?', '["HO-6","HO-2","HO-4","HO-8"]'::jsonb, 'HO-6', 'The HO-6 covers a condo owner''s personal property, the owner''s building items and improvements (Coverage A), loss of use, and liability.', 'HO-6 = condo.', null),
('homeowners', 'medium', 'Which homeowners form is used for older homes whose replacement cost greatly exceeds market value?', '["HO-4","HO-8 (Modified Coverage)","HO-3","HO-6"]'::jsonb, 'HO-8 (Modified Coverage)', 'The HO-8 is for homes where replacement cost is much higher than market value. It generally settles losses using functional replacement cost or actual cash value and covers basic named perils.', 'Old home, RC far above market value = HO-8.', null),
('homeowners', 'medium', 'Under the HO-3, the dwelling (Coverage A) is covered on what basis?', '["Open perils (special), subject to exclusions","Basic named perils","Broad named perils","Fire only"]'::jsonb, 'Open perils (special), subject to exclusions', 'The HO-3 covers Coverages A and B against open perils, and Coverage C against broad named perils.', 'HO-3 = open perils on dwelling, named perils on contents.', null),
('homeowners', 'medium', 'Under an unendorsed HO-3, personal property (Coverage C) is covered against:', '["Broad named perils","Basic named perils only","All perils including flood","Open perils"]'::jsonb, 'Broad named perils', 'Coverage C in the HO-3 is named perils, the same broad list used in the HO-2. The HO-5 or an endorsement is needed for open perils on contents.', 'HO-3 contents = named perils.', null),
('homeowners', 'medium', 'Under an HO-3 with a Coverage A limit of $300,000, what is the Coverage B (other structures) limit?', '["$150,000","$30,000","$60,000","$15,000"]'::jsonb, '$30,000', 'Coverage B equals 10% of Coverage A: $300,000 × 10% = $30,000.', 'Cov B = 10% of A.', null),
('homeowners', 'medium', 'Under an HO-3 with a Coverage A limit of $300,000, what is the Coverage C (personal property) limit?', '["$30,000","$150,000","$300,000","$90,000"]'::jsonb, '$150,000', 'Coverage C equals 50% of Coverage A: $300,000 × 50% = $150,000.', 'Cov C = 50% of A.', null),
('homeowners', 'medium', 'Under an HO-3, the Coverage D (loss of use) limit equals what percentage of Coverage A?', '["50%","20%","10%","30%"]'::jsonb, '30%', 'On the HO-2 and HO-3, Coverage D equals 30% of Coverage A. It includes additional living expense and fair rental value.', 'Cov D = 30% of A (HO-2/3).', null),
('homeowners', 'hard', 'Under the HO-3 replacement cost loss settlement, the insurer pays full replacement cost for a covered dwelling loss (up to the limit) when the Coverage A limit is at least what percentage of the dwelling''s replacement cost at the time of loss?', '["90%","80%","50%","100%"]'::jsonb, '80%', 'If Coverage A is at least 80% of full replacement cost, the insurer pays replacement cost without deduction for depreciation, up to the limit. If not, it pays the greater of ACV or a proportion of replacement cost.', '80% insurance-to-value = full RC.', null),
('homeowners', 'medium', 'Homeowners Section II includes which two coverages?', '["Coverage C – Personal property and Coverage D – Loss of use","Coverage E – Personal liability and Coverage F – Medical payments to others","Collision and other than collision","Coverage A – Dwelling and Coverage B – Other structures"]'::jsonb, 'Coverage E – Personal liability and Coverage F – Medical payments to others', 'Section I covers property (A through D). Section II covers personal liability (E) and medical payments to others (F).', 'Section II = E (liability) + F (med pay to others).', null),
('homeowners', 'medium', 'Homeowners Coverage F (medical payments to others) does NOT pay for injuries to:', '["A neighbor injured by the insured''s golf ball away from the premises","A guest injured on the premises","A delivery person bitten by the insured''s dog","The named insured or regular household residents"]'::jsonb, 'The named insured or regular household residents', 'Medical payments to others pays regardless of fault for injuries to others, not to the insured or regular household members (other than residence employees).', 'Med pay to others excludes the insured''s household.', null),
('homeowners', 'medium', 'What is the standard minimum Coverage E personal liability limit on a homeowners policy?', '["$25,000 per occurrence","$100,000 per occurrence","$500,000 per occurrence","$1,000,000 per occurrence"]'::jsonb, '$100,000 per occurrence', 'The basic homeowners liability limit is $100,000 per occurrence, and it can be increased.', 'HO liability starts at $100,000.', null),
('homeowners', 'hard', 'Under the HO-3''s special limits of liability, theft of jewelry, watches, and furs is limited to:', '["$200","$1,500","$5,000","$2,500"]'::jsonb, '$1,500', 'The HO special limits include $200 for money, $1,500 for theft of jewelry and furs, and $2,500 for theft of firearms and silverware. Higher values are scheduled with the scheduled personal property endorsement.', 'Jewelry theft sublimit = $1,500.', null),
('homeowners', 'hard', 'Under the HO-3''s special limits of liability, money and bank notes are limited to:', '["$2,500","$200","$1,500","$500"]'::jsonb, '$200', 'Money, bank notes, and similar items carry a $200 special limit. Securities and valuable papers are limited to $1,500.', 'Money = $200.', null),
('homeowners', 'medium', 'A homeowner wants full coverage for a $12,000 engagement ring, including mysterious disappearance. The best solution is:', '["The scheduled personal property endorsement (HO 04 61)","The personal property replacement cost endorsement (HO 04 90)","An HO-4 policy","Raising Coverage C"]'::jsonb, 'The scheduled personal property endorsement (HO 04 61)', 'Scheduling the ring removes the theft sublimit and provides broad coverage on the scheduled item, usually without a deductible.', 'High-value jewelry = schedule it.', null),
('homeowners', 'medium', 'The personal property replacement cost endorsement (HO 04 90) changes Coverage C loss settlement from:', '["Replacement cost to actual cash value","Named perils to open perils","Scheduled to blanket","Actual cash value to replacement cost"]'::jsonb, 'Actual cash value to replacement cost', 'Unendorsed homeowners forms settle personal property at ACV. HO 04 90 changes that to replacement cost.', 'HO 04 90 = RC on contents.', null),
('homeowners', 'medium', 'Earthquake damage to a home is excluded under the HO-3 unless:', '["The home is in Wisconsin","The loss is less than $5,000","The earthquake endorsement (HO 04 54) is added","The insured has flood insurance"]'::jsonb, 'The earthquake endorsement (HO 04 54) is added', 'Earth movement is excluded. The earthquake endorsement adds the coverage, usually with a percentage deductible.', 'Earthquake needs HO 04 54.', null),
('homeowners', 'medium', 'Water that backs up through a basement floor drain is excluded under an unendorsed HO-3. Which endorsement adds this coverage?', '["Home day care (HO 04 97)","Water back-up and sump discharge or overflow (HO 04 95)","Earthquake (HO 04 54)","Scheduled personal property (HO 04 61)"]'::jsonb, 'Water back-up and sump discharge or overflow (HO 04 95)', 'Sewer and drain back-up and sump overflow are excluded. The HO 04 95 endorsement adds limited coverage.', 'Sewer backup = HO 04 95.', null),
('homeowners', 'medium', 'An insured runs a licensed day care business from her home. What should her agent recommend?', '["The earthquake endorsement","A higher Coverage A limit","The home day care endorsement (HO 04 97) or a separate commercial policy","Nothing; homeowners covers home businesses automatically"]'::jsonb, 'The home day care endorsement (HO 04 97) or a separate commercial policy', 'Business pursuits, including home day care, are largely excluded under homeowners Section II. The home day care endorsement or a commercial policy is needed.', 'Home day care = HO 04 97 or commercial coverage.', null),
('homeowners', 'medium', 'Which is excluded under homeowners Section II (liability)?', '["Injury to a guest who slips on an icy sidewalk","Damage caused by the insured''s child breaking a neighbor''s window","A golf ball hitting another golfer","Bodily injury the insured expected or intended"]'::jsonb, 'Bodily injury the insured expected or intended', 'Section II excludes expected or intended injury, business pursuits, professional services, most motor vehicles, and injury to insureds, among others. Accidental injuries to others are covered.', 'Intentional acts are not covered.', null),
('homeowners', 'hard', 'Mold damage under the HO-3 is generally excluded except for limited coverage that can be provided by:', '["The scheduled personal property endorsement","The limited fungi, wet or dry rot, or bacteria endorsement (HO 04 26/HO 04 27)","The personal property replacement cost endorsement","The earthquake endorsement"]'::jsonb, 'The limited fungi, wet or dry rot, or bacteria endorsement (HO 04 26/HO 04 27)', 'Fungi, wet or dry rot, and bacteria are excluded. The limited fungi endorsements provide specified limits of coverage.', 'Mold coverage = HO 04 26/27.', null),
('homeowners', 'medium', 'Which peril is covered under the HO-2 broad form but NOT under a basic named perils form?', '["Fire","Windstorm","Falling objects","Lightning"]'::jsonb, 'Falling objects', 'Broad form adds perils such as falling objects; weight of ice, snow, or sleet; accidental discharge of water or steam; freezing; and sudden and accidental damage from artificially generated electrical current.', 'Broad adds falling objects, weight of ice/snow, freezing, water discharge.', null),
('homeowners', 'medium', 'Under the HO-3, how are trees, shrubs, and plants covered?', '["Under Coverage E","They are fully excluded","As an additional coverage for named perils, with a per-item limit, not including windstorm","Under Coverage A on an open perils basis"]'::jsonb, 'As an additional coverage for named perils, with a per-item limit, not including windstorm', 'Trees, shrubs, and plants are an additional coverage for specified perils (not windstorm), subject to a per-tree limit and an overall percentage of Coverage A.', 'Trees: additional coverage, named perils, no wind.', null),
('homeowners', 'medium', 'Under homeowners policies, the vacancy exclusion for vandalism and malicious mischief applies after the dwelling has been vacant for more than:', '["60 consecutive days","14 consecutive days","90 consecutive days","30 consecutive days"]'::jsonb, '60 consecutive days', 'Vandalism, malicious mischief, and glass breakage coverage is excluded if the dwelling has been vacant more than 60 consecutive days before the loss.', '60 consecutive days vacant.', null),
('homeowners', 'hard', 'Which statement about watercraft under an unendorsed homeowners policy is correct?', '["Section II covers some small boats, but larger or higher-horsepower boats need a watercraft endorsement or boatowners policy","No watercraft is ever covered","All boats are fully covered under Section I and Section II","Watercraft is covered only while on the insured''s premises"]'::jsonb, 'Section II covers some small boats, but larger or higher-horsepower boats need a watercraft endorsement or boatowners policy', 'Section II excludes liability for many owned watercraft above certain size and horsepower thresholds, and Section I has a low special limit for watercraft. Larger boats need an endorsement or a boatowners policy.', 'Bigger boats need an endorsement or boat policy.', null),
('homeowners', 'medium', 'Under homeowners Section I, the deductible generally applies:', '["Per occurrence to Section I property losses","To Section II liability claims","Per item damaged","Only to theft losses"]'::jsonb, 'Per occurrence to Section I property losses', 'The homeowners deductible applies per occurrence to Section I property losses. It does not apply to Section II liability or medical payments.', 'Deductible = Section I, per occurrence.', null),
('personal_other', 'medium', 'Flood insurance is available through the National Flood Insurance Program only when:', '["The owner has a mortgage","The owner has an HO-3","The property is in a high-risk flood zone only","The property is in a community that participates in the NFIP"]'::jsonb, 'The property is in a community that participates in the NFIP', 'NFIP coverage is available in participating communities, which agree to adopt floodplain management rules. It is available in and outside high-risk zones.', 'NFIP requires a participating community.', null),
('personal_other', 'medium', 'New NFIP flood policies generally have a waiting period before coverage takes effect of:', '["30 days","10 days","60 days","No waiting period"]'::jsonb, '30 days', 'Most new NFIP policies have a 30-day waiting period. Exceptions include coverage bought in connection with making, increasing, or renewing a loan.', 'NFIP waiting period = 30 days (with exceptions).', null),
('personal_other', 'hard', 'What is the maximum NFIP building coverage for a single-family residence?', '["$500,000","$100,000","$250,000","$1,000,000"]'::jsonb, '$250,000', 'The NFIP residential limits are $250,000 for the building and $100,000 for contents. Excess flood coverage is available in the private market.', 'NFIP residential: $250K building, $100K contents.', null),
('personal_other', 'medium', 'Under the NFIP "Write Your Own" program:', '["Homeowners write their own flood policy terms","Only FEMA may sell flood coverage","Private insurers issue and service flood policies under their own names, with the federal government bearing the risk","Agents may change NFIP policy terms"]'::jsonb, 'Private insurers issue and service flood policies under their own names, with the federal government bearing the risk', 'In the WYO program, participating private insurers sell and service NFIP policies, while the federal program underwrites the risk. Coverage terms are the same as direct NFIP policies.', 'WYO = private insurer sells; government takes the risk.', null),
('personal_other', 'medium', 'A family wants coverage for its 24-foot boat with a 200-horsepower engine, including liability. The best choice is:', '["A personal auto policy","Relying on the homeowners policy","A dwelling fire policy","A boatowners policy"]'::jsonb, 'A boatowners policy', 'Homeowners forms give very limited watercraft property coverage and exclude liability for larger boats. A boatowners policy provides hull, equipment, and liability coverage.', 'Larger boats = boatowners policy.', null),
('personal_other', 'medium', 'A mobile home policy is generally written:', '["As a homeowners-type form adapted for manufactured homes at a fixed location","Under a personal auto policy","Only through the NFIP","Only on a commercial form"]'::jsonb, 'As a homeowners-type form adapted for manufactured homes at a fixed location', 'Manufactured and mobile homes are generally insured on homeowners-type forms adapted by endorsement or a separate program, covering the home, contents, and liability.', 'Mobile homes use adapted homeowners-type coverage.', null),
('personal_other', 'medium', 'Earthquake insurance typically uses which type of deductible?', '["A percentage of the dwelling''s limit","A flat $100 deductible","No deductible","A deductible equal to one year''s premium"]'::jsonb, 'A percentage of the dwelling''s limit', 'Earthquake coverage usually has a percentage deductible, such as 5% to 20% of the Coverage A limit, because losses can be catastrophic.', 'Earthquake = percentage deductible.', null),
('personal_other', 'medium', 'Directors and officers (D&O) liability insurance protects:', '["Employees injured on the job","Directors and officers against claims alleging wrongful acts in managing the organization","Customers injured by products","The organization''s buildings"]'::jsonb, 'Directors and officers against claims alleging wrongful acts in managing the organization', 'D&O covers claims of wrongful acts, such as mismanagement or breach of duty, against directors and officers. Many D&O policies also reimburse the organization when it indemnifies them.', 'D&O = management wrongful acts.', null),
('personal_other', 'hard', 'Which statement about NFIP flood coverage for a basement is correct?', '["Coverage for basement contents and improvements is limited","Basements are always excluded entirely","Basements are covered only for sewer backup","Basement contents are covered in full"]'::jsonb, 'Coverage for basement contents and improvements is limited', 'NFIP coverage in basements is restricted: it covers certain building items and equipment, and many contents and finished improvements are not covered.', 'NFIP basement coverage is limited.', null),
('personal_other', 'medium', 'Which peril is excluded under standard homeowners forms and handled by the NFIP?', '["Theft","Flood","Windstorm","Fire"]'::jsonb, 'Flood', 'Flood and surface water are excluded under homeowners and dwelling forms. The NFIP and private flood insurers fill the gap.', 'Flood needs a flood policy.', null),
('personal_other', 'medium', 'An NFIP-defined flood generally requires:', '["Any water damage in the home","A general and temporary condition of inundation of normally dry land affecting two or more acres or two or more properties","A burst pipe","Rain entering through a broken window"]'::jsonb, 'A general and temporary condition of inundation of normally dry land affecting two or more acres or two or more properties', 'The NFIP definition requires a general and temporary inundation of two or more acres of normally dry land or two or more properties, or mudflow. A burst pipe is not a flood.', 'Flood = 2+ acres or 2+ properties inundated.', null),
('casualty_basics', 'easy', 'Negligence is best defined as:', '["An intentional wrongful act","A breach of a written contract","Any act that causes injury","Failure to use the care a reasonably prudent person would use in the same circumstances"]'::jsonb, 'Failure to use the care a reasonably prudent person would use in the same circumstances', 'Negligence is failing to exercise reasonable care. Liability insurance primarily responds to claims of negligence.', 'Negligence = failing to act as a reasonable person would.', null),
('casualty_basics', 'medium', 'Which set lists the four elements needed to prove negligence?', '["Legal duty, breach of that duty, proximate cause, and actual damages","Contract, breach, notice, and damages","Intent, motive, opportunity, and damages","Duty, warning, consent, and loss"]'::jsonb, 'Legal duty, breach of that duty, proximate cause, and actual damages', 'A plaintiff must prove a legal duty owed, a breach of that duty, that the breach proximately caused the harm, and actual damages.', 'Duty, breach, cause, damages.', null),
('casualty_basics', 'medium', 'A tort is:', '["A crime prosecuted by the state","A written insurance agreement","A civil wrong, other than a breach of contract, for which a court may award damages","A type of reinsurance"]'::jsonb, 'A civil wrong, other than a breach of contract, for which a court may award damages', 'Torts are civil wrongs such as negligence, intentional torts, and strict liability. Liability policies respond mainly to negligence-based tort claims.', 'Tort = civil wrong (not a contract breach).', null),
('casualty_basics', 'medium', 'Medical bills and lost wages in a bodily injury lawsuit are examples of:', '["Punitive damages","Nominal damages","Special compensatory damages","General compensatory damages"]'::jsonb, 'Special compensatory damages', 'Special damages are measurable out-of-pocket losses. General damages compensate for things without a precise dollar value, such as pain and suffering. Punitive damages punish gross misconduct.', 'Special = specific costs. General = pain and suffering.', null),
('casualty_basics', 'medium', 'Damages meant to punish a defendant for gross or reckless misconduct are called:', '["General damages","Punitive damages","Liquidated damages","Special damages"]'::jsonb, 'Punitive damages', 'Punitive (exemplary) damages punish and deter. They are not tied to the plaintiff''s actual loss.', 'Punish = punitive.', null),
('casualty_basics', 'medium', 'An owner who keeps a wild animal is liable for injuries it causes even if the owner used all possible care. This is:', '["Comparative negligence","Contributory negligence","Strict (absolute) liability","Vicarious liability"]'::jsonb, 'Strict (absolute) liability', 'Strict or absolute liability applies to inherently dangerous activities and wild animals regardless of fault.', 'Dangerous activity, no fault needed = strict liability.', null),
('casualty_basics', 'medium', 'An employer is held liable for an accident an employee caused while making deliveries. This is:', '["Contractual liability","Strict liability","Vicarious liability","Absolute liability"]'::jsonb, 'Vicarious liability', 'Vicarious liability holds one party responsible for another''s negligence because of their relationship, such as employer and employee.', 'Liable for someone else''s acts = vicarious.', null),
('casualty_basics', 'hard', 'Under a modified comparative negligence rule, a plaintiff who is 30% at fault and has $100,000 in damages generally recovers:', '["$70,000","$100,000","$0","$30,000"]'::jsonb, '$70,000', 'Comparative negligence reduces recovery by the plaintiff''s share of fault: $100,000 × 70% = $70,000. Under modified rules, recovery is barred if the plaintiff''s fault exceeds a threshold.', 'Recovery reduced by your % of fault.', null),
('casualty_basics', 'medium', 'Which is a common defense against a negligence claim?', '["Assumption of risk","Strict liability","Res ipsa loquitur","Vicarious liability"]'::jsonb, 'Assumption of risk', 'Defenses include comparative or contributory negligence and assumption of risk (the plaintiff knowingly accepted a danger).', 'Assumption of risk is a negligence defense.', null),
('casualty_basics', 'medium', 'An auto policy with limits of 100/300/50 pays a maximum of how much for bodily injury to one person?', '["$50,000","$300,000","$450,000","$100,000"]'::jsonb, '$100,000', 'Split limits read per person bodily injury / per accident bodily injury / property damage. 100/300/50 means $100,000 per person.', 'Split limits: per person / per accident / PD.', null),
('casualty_basics', 'medium', 'A single limit that applies to bodily injury and property damage combined for each occurrence is a:', '["Split limit","Per person limit","Combined single limit","Aggregate limit"]'::jsonb, 'Combined single limit', 'A combined single limit (CSL) is one per-occurrence amount for all BI and PD, rather than separate limits.', 'CSL = one limit for BI + PD.', null),
('casualty_basics', 'medium', 'Liability policies usually pay defense costs:', '["Only if the insured wins the case","As part of the deductible","In addition to the limits of liability, until the limit is exhausted by payment of judgments or settlements","Only after the limit is used up"]'::jsonb, 'In addition to the limits of liability, until the limit is exhausted by payment of judgments or settlements', 'The duty to defend typically sits outside the limits (supplementary payments) and ends when the insurer has used up the limit paying judgments or settlements.', 'Defense is outside limits; ends when limits are paid out.', null),
('casualty_basics', 'medium', 'A self-insured retention (SIR) differs from a deductible because:', '["An SIR never applies to defense costs","An SIR applies only to property coverage","The insured pays losses and often handles claims within the SIR before the insurer responds","The insurer pays first and then collects the SIR"]'::jsonb, 'The insured pays losses and often handles claims within the SIR before the insurer responds', 'With an SIR, the insured funds and often administers losses up to the retention. With a deductible, the insurer typically handles the claim and the deductible reduces the payment.', 'SIR = insured pays first; the insurer responds above it.', null),
('casualty_basics', 'medium', 'A liability policy''s arbitration provision is used to:', '["Assign the policy to another insurer","Cancel the policy","Resolve disputes, such as the amount of damages, through a neutral third party instead of court","Increase policy limits"]'::jsonb, 'Resolve disputes, such as the amount of damages, through a neutral third party instead of court', 'Arbitration resolves disputes, such as those under uninsured motorist coverage, through neutral arbitrators rather than litigation.', 'Arbitration = neutral resolution instead of court.', null),
('casualty_basics', 'medium', 'An aggregate limit is:', '["The limit that applies to defense costs only","The most the policy will pay for all covered claims during the policy period","The deductible for each claim","The most paid for one person''s injury"]'::jsonb, 'The most the policy will pay for all covered claims during the policy period', 'An aggregate limit caps total payments for the policy period, such as the CGL''s general aggregate and products-completed operations aggregate.', 'Aggregate = total cap for the policy period.', null),
('casualty_basics', 'medium', 'A liability policy''s primary and excess other-insurance approach means:', '["Both policies split every loss equally","Only one policy pays and the other is void","The excess policy pays first","The primary policy pays first up to its limits, then the excess policy pays"]'::jsonb, 'The primary policy pays first up to its limits, then the excess policy pays', 'Primary coverage responds first. Excess coverage applies only after the primary limits are exhausted.', 'Primary first, then excess.', null),
('casualty_basics', 'hard', 'Which statement about the insurer''s duty to defend is most accurate?', '["It generally applies to suits seeking covered damages, even if the allegations are groundless or false","It applies only if the insured is actually at fault","It ends when a suit is filed","It applies to criminal charges"]'::jsonb, 'It generally applies to suits seeking covered damages, even if the allegations are groundless or false', 'The duty to defend is broader than the duty to pay. The insurer must defend suits seeking covered damages, even groundless, false, or fraudulent ones.', 'Defend even groundless suits for covered damages.', null),
('casualty_basics', 'medium', 'Liability insurance is designed to pay:', '["Only the insured''s medical bills","The insured''s own property losses","Sums the insured becomes legally obligated to pay others for covered injury or damage","Fines and penalties imposed by a court"]'::jsonb, 'Sums the insured becomes legally obligated to pay others for covered injury or damage', 'Liability insurance responds to the insured''s legal obligations to third parties. Criminal fines and penalties are generally not insurable.', 'Liability = legally obligated to pay others.', null),
('personal_auto', 'easy', 'Under the personal auto policy (PAP), Part A provides:', '["Uninsured motorists","Medical payments","Damage to your auto","Liability coverage"]'::jsonb, 'Liability coverage', 'PAP parts: A – Liability, B – Medical payments, C – Uninsured motorists, D – Coverage for damage to your auto, E – Duties after an accident or loss, F – General provisions.', 'A Liability, B Med pay, C UM, D Physical damage.', null),
('personal_auto', 'medium', 'Under the PAP, hitting a deer is covered under:', '["Other than collision (comprehensive)","Liability","Uninsured motorists","Collision"]'::jsonb, 'Other than collision (comprehensive)', 'Contact with a bird or animal is specifically listed as an other-than-collision loss, as are fire, theft, windstorm, hail, and glass breakage.', 'Animal hit = OTC, not collision.', null),
('personal_auto', 'medium', 'A car slides on ice and rolls over. The damage is covered under:', '["Other than collision","Medical payments","Liability","Collision"]'::jsonb, 'Collision', 'Collision means upset (overturn) of the auto or its impact with another vehicle or object.', 'Upset or overturn = collision.', null),
('personal_auto', 'hard', 'PAP supplementary payments include reimbursement for loss of earnings because of attendance at hearings or trials at the insurer''s request, up to:', '["$50 per day","$200 per day","$500 per day","$250 per day"]'::jsonb, '$200 per day', 'PAP supplementary payments include up to $250 for bail bonds and up to $200 a day for loss of earnings from attending hearings or trials at the insurer''s request.', 'Bail $250; lost earnings $200/day.', null),
('personal_auto', 'hard', 'Under PAP Part D transportation expenses, the insurer pays up to:', '["$20 per day, to a maximum of $600","$10 per day, to a maximum of $300","$30 per day, to a maximum of $900","$50 per day, to a maximum of $1,500"]'::jsonb, '$20 per day, to a maximum of $600', 'The PAP provides $20 per day up to $600 for temporary transportation expenses. For theft, coverage begins 48 hours after the theft; for other losses, 24 hours after the auto is withdrawn from use.', '$20/day, $600 max.', null),
('personal_auto', 'medium', 'The PAP policy territory includes:', '["Worldwide","Only the state where the auto is garaged","The United States, its territories and possessions, Puerto Rico, and Canada","The United States and Mexico"]'::jsonb, 'The United States, its territories and possessions, Puerto Rico, and Canada', 'The PAP covers accidents in the U.S., its territories or possessions, Puerto Rico, and Canada, and while the auto is transported between their ports.', 'U.S., territories, Puerto Rico, Canada. Not Mexico.', null),
('personal_auto', 'medium', 'Which vehicle is excluded from PAP liability coverage?', '["A borrowed car the insured drives occasionally","A replacement auto the insured just bought","A rental car on vacation","A vehicle with fewer than four wheels owned by the insured"]'::jsonb, 'A vehicle with fewer than four wheels owned by the insured', 'PAP liability excludes owned vehicles with fewer than four wheels, such as motorcycles, as well as vehicles used as a public or livery conveyance.', 'Owned motorcycles aren''t covered.', null),
('personal_auto', 'medium', 'PAP Part B medical payments covers:', '["Only the other driver''s injuries","Reasonable medical and funeral expenses for insureds from an auto accident, regardless of fault","Damage to the insured''s vehicle","Lost wages of the insured"]'::jsonb, 'Reasonable medical and funeral expenses for insureds from an auto accident, regardless of fault', 'Medical payments is no-fault coverage for insureds and occupants of the covered auto, for expenses incurred within a set time after the accident.', 'Med pay = no-fault medical for insureds and occupants.', null),
('personal_auto', 'hard', 'A PAP insured buys an additional (not replacement) car. For liability coverage to apply automatically, the insured must request coverage within:', '["60 days","4 days","14 days after becoming the owner","30 days"]'::jsonb, '14 days after becoming the owner', 'Newly acquired additional autos get liability coverage if the insured asks for coverage within 14 days. A replacement auto gets the broadest coverage on any vehicle for the rest of the policy period.', 'New additional auto = 14 days to tell the insurer.', null),
('personal_auto', 'hard', 'A PAP insured buys a new car and no vehicle on the policy carries collision coverage. Collision applies to the newly acquired car only if the insured asks for it within:', '["4 days","30 days","It never applies","14 days"]'::jsonb, '4 days', 'If collision exists on at least one vehicle, the insured has 14 days to request coverage on a newly acquired auto. If no vehicle has it, the insured has 4 days, and a deductible applies.', 'No existing collision = 4 days.', null),
('personal_auto', 'medium', 'The PAP does not cover a covered auto while it is being used to carry paying passengers as a public or livery conveyance. A share-the-expense car pool is:', '["Not considered a public or livery conveyance, so coverage applies","Covered only under collision","Excluded under the same rule","Covered only if disclosed at application"]'::jsonb, 'Not considered a public or livery conveyance, so coverage applies', 'The public or livery conveyance exclusion does not apply to share-the-expense car pools.', 'Carpools are fine; taxi-style use isn''t.', null),
('personal_auto', 'medium', 'After an accident, the PAP requires the insured to:', '["Settle directly with the other driver","Wait until a lawsuit is filed before reporting","Promptly notify the insurer and cooperate in the investigation, settlement, or defense","Get two repair estimates before notifying the insurer"]'::jsonb, 'Promptly notify the insurer and cooperate in the investigation, settlement, or defense', 'Part E duties include prompt notice, cooperation, sending legal papers, submitting to exams if asked, and protecting the auto from further loss.', 'Notify promptly and cooperate.', null),
('personal_auto', 'medium', 'Which endorsement adds coverage for towing and labor at the place of breakdown?', '["Joint ownership coverage (PP 03 34)","Miscellaneous type vehicle (PP 03 23)","Towing and labor costs (PP 03 03)","Extended non-owned coverage (PP 03 06)"]'::jsonb, 'Towing and labor costs (PP 03 03)', 'PP 03 03 pays towing and labor costs incurred at the place of disablement, up to the selected limit.', 'Towing = PP 03 03.', null),
('personal_auto', 'hard', 'An employee regularly drives a company car. To cover personal liability while driving it, the employee should add:', '["Joint ownership coverage (PP 03 34)","Extended non-owned coverage – vehicles furnished or available for regular use (PP 03 06)","Miscellaneous type vehicle (PP 03 23)","Towing and labor costs (PP 03 03)"]'::jsonb, 'Extended non-owned coverage – vehicles furnished or available for regular use (PP 03 06)', 'The PAP excludes vehicles furnished or available for the insured''s regular use. PP 03 06 removes that exclusion.', 'Regular use of a non-owned car = PP 03 06.', null),
('personal_auto', 'medium', 'Which endorsement is used to insure a motorcycle, motor home, or golf cart under the PAP?', '["Miscellaneous type vehicle (PP 03 23)","Extended non-owned coverage (PP 03 06)","Towing and labor costs (PP 03 03)","Amendment of policy provisions (PP 01 93)"]'::jsonb, 'Miscellaneous type vehicle (PP 03 23)', 'The miscellaneous type vehicle endorsement extends PAP coverage to motorcycles, mopeds, motor homes, golf carts, and similar vehicles.', 'Motorcycles/motor homes = PP 03 23.', null),
('personal_auto', 'medium', 'Two unmarried people who jointly own a car and want it insured on one PAP should use:', '["Joint ownership coverage (PP 03 34)","Towing and labor costs (PP 03 03)","Extended non-owned coverage (PP 03 06)","Miscellaneous type vehicle (PP 03 23)"]'::jsonb, 'Joint ownership coverage (PP 03 34)', 'The PAP is written for an individual or a married couple in the same household. PP 03 34 adapts it for joint owners who are not married.', 'Unmarried joint owners = PP 03 34.', null),
('commercial_auto', 'medium', 'In the business auto coverage form, covered auto symbol 1 means:', '["Any auto","Specifically described autos","Owned autos only","Hired autos only"]'::jsonb, 'Any auto', 'Symbol 1 is the broadest: any auto. Symbol 2 is owned autos only, 7 is specifically described autos, 8 is hired autos, and 9 is non-owned autos.', 'Symbol 1 = any auto.', null),
('commercial_auto', 'medium', 'A business wants liability coverage for employees who use their own cars on company errands. Which covered auto symbol applies?', '["Symbol 7 – Specifically described autos","Symbol 9 – Non-owned autos","Symbol 8 – Hired autos","Symbol 2 – Owned autos only"]'::jsonb, 'Symbol 9 – Non-owned autos', 'Symbol 9 covers autos the business does not own, lease, hire, rent, or borrow that are used in its business, such as employees'' personal cars.', 'Employee cars on business = symbol 9.', null),
('commercial_auto', 'medium', 'Garagekeepers coverage protects an auto repair shop against:', '["Damage to its own tow trucks","Damage to customers'' autos in its care, custody, or control","Injury to its employees","Theft of its tools"]'::jsonb, 'Damage to customers'' autos in its care, custody, or control', 'Garage liability excludes damage to property in the insured''s care, custody, or control. Garagekeepers coverage fills that gap for customers'' vehicles.', 'Customers'' cars in the shop = garagekeepers.', null),
('commercial_auto', 'medium', 'Which commercial auto form is designed for businesses that haul goods for others, such as motor carriers?', '["Personal auto policy","Business auto coverage form","Garage coverage form","Motor carrier coverage form"]'::jsonb, 'Motor carrier coverage form', 'The motor carrier and truckers forms address for-hire trucking operations. The business auto form is the general-purpose commercial auto form.', 'For-hire trucking = motor carrier/truckers form.', null),
('commercial_auto', 'hard', 'The Motor Carrier Act of 1980 requires regulated motor carriers to:', '["Carry no liability insurance if they are self-insured","Maintain minimum levels of financial responsibility, evidenced by a filing such as the MCS-90 endorsement","Buy coverage only from state-run insurers","Insure only the cargo they haul"]'::jsonb, 'Maintain minimum levels of financial responsibility, evidenced by a filing such as the MCS-90 endorsement', 'The Act sets minimum financial responsibility for interstate motor carriers. The MCS-90 endorsement guarantees payment to the public up to the required amount, even if the policy would not otherwise apply, with the insurer able to seek reimbursement from the carrier.', 'Motor Carrier Act → MCS-90 public liability guarantee.', null),
('commercial_auto', 'medium', 'The drive other car coverage endorsement is used when:', '["A business rents cars for employees","An executive has a company car and no personal auto policy, and needs coverage while driving other cars","A dealer lends cars to customers","An employee uses a personal car on business"]'::jsonb, 'An executive has a company car and no personal auto policy, and needs coverage while driving other cars', 'Drive other car extends business auto coverage to named individuals, such as officers who have no personal auto policy, while they drive autos the business does not own.', 'Company-car executives without a PAP = drive other car.', null),
('commercial_auto', 'medium', 'Trailer interchange coverage protects a trucker for:', '["Damage to another party''s trailer in the insured''s possession under a written trailer interchange agreement","Employee injuries","Cargo losses","Liability for injuries caused by its trucks"]'::jsonb, 'Damage to another party''s trailer in the insured''s possession under a written trailer interchange agreement', 'Trailer interchange covers physical damage to non-owned trailers the insured has under a written interchange agreement.', 'Someone else''s trailer under an interchange agreement.', null),
('commercial_auto', 'medium', 'When a business sole proprietor is the named insured on a business auto policy, which endorsement gives the individual and family members personal-auto-type coverage?', '["Individual named insured endorsement","Lessor – additional insured and loss payee","Employees as insureds endorsement","Mobile equipment endorsement"]'::jsonb, 'Individual named insured endorsement', 'The individual named insured endorsement adds PAP-like coverage for the individual and family members when the business auto policy names an individual.', 'Individual as named insured = add PAP-like coverage.', null),
('commercial_liability', 'easy', 'CGL Coverage A provides:', '["Property coverage for the insured''s building","Medical payments","Bodily injury and property damage liability","Personal and advertising injury liability"]'::jsonb, 'Bodily injury and property damage liability', 'CGL parts: Coverage A – BI and PD liability, Coverage B – Personal and advertising injury, Coverage C – Medical payments.', 'A = BI/PD, B = personal & advertising injury, C = med pay.', null),
('commercial_liability', 'medium', 'A store owner is sued for falsely accusing a customer of shoplifting and detaining her. Which CGL coverage responds?', '["Coverage C – Medical payments","Coverage A – Bodily injury and property damage","Coverage B – Personal and advertising injury","No coverage applies"]'::jsonb, 'Coverage B – Personal and advertising injury', 'False arrest, detention, or imprisonment, malicious prosecution, libel, slander, and invasion of privacy are personal and advertising injury offenses under Coverage B.', 'False arrest, libel, slander = Coverage B.', null),
('commercial_liability', 'medium', 'CGL Coverage C medical payments pays:', '["Only if the insured is found negligent","Employees'' injuries on the job","Medical expenses for injuries on the insured''s premises or from its operations, regardless of fault","The insured''s own medical bills"]'::jsonb, 'Medical expenses for injuries on the insured''s premises or from its operations, regardless of fault', 'Coverage C pays regardless of fault, which can prevent lawsuits. It excludes injuries to insureds and employees (who are covered by workers compensation).', 'CGL med pay = no-fault, no employees.', null),
('commercial_liability', 'medium', 'Under an occurrence CGL policy, which policy responds to a claim?', '["The policy with the highest limits","The policy in force when the claim is first made","The policy in force when the lawsuit is decided","The policy in force when the injury or damage occurred"]'::jsonb, 'The policy in force when the injury or damage occurred', 'Occurrence policies are triggered by injury or damage during the policy period, even if the claim is made years later.', 'Occurrence trigger = when injury happened.', null),
('commercial_liability', 'medium', 'Under a claims-made CGL, the retroactive date means:', '["No coverage applies to injury or damage that occurred before that date","The policy starts paying on that date","Claims must be made before that date","Premium is refunded after that date"]'::jsonb, 'No coverage applies to injury or damage that occurred before that date', 'A claims-made policy covers claims first made during the policy period for injury or damage that occurs on or after the retroactive date.', 'Injury must occur after the retro date.', null),
('commercial_liability', 'hard', 'Under a claims-made CGL, the basic extended reporting period is provided:', '["Never; claims-made policies have no tail","Automatically, without additional premium","Only if the insured requests it within one year","Only by endorsement for an additional premium"]'::jsonb, 'Automatically, without additional premium', 'The basic ERP (tail) is automatic and free. The supplemental ERP is optional, purchased by endorsement for an additional premium, and can be unlimited in duration.', 'Basic tail = automatic and free; supplemental = extra premium.', null),
('commercial_liability', 'medium', 'The CGL products-completed operations hazard covers:', '["Employee injuries","Injury or damage arising from the insured''s products or completed work away from its premises","Damage to the insured''s own products","Injuries on premises during business hours only"]'::jsonb, 'Injury or damage arising from the insured''s products or completed work away from its premises', 'Products-completed operations covers claims from products after they leave the insured''s control and from work after it is completed. It has its own aggregate limit.', 'Products after they leave, work after it''s done.', null),
('commercial_liability', 'hard', 'Under the CGL, contractual liability coverage applies to liability the insured assumes under an "insured contract," such as:', '["A lease of premises or a hold harmless agreement where the insured assumes another''s tort liability","A promise to deliver goods on time","An employment contract","A warranty of product quality"]'::jsonb, 'A lease of premises or a hold harmless agreement where the insured assumes another''s tort liability', 'The CGL contractual liability exclusion does not apply to liability assumed in an insured contract, which includes premises leases and agreements assuming another''s tort liability. Breach of contract itself is not covered.', 'Assumed tort liability in an insured contract is covered.', null),
('commercial_liability', 'medium', 'Which is excluded under the CGL Coverage A?', '["A customer tripping over a box in the aisle","Injury caused by a product the insured sold","Bodily injury to the insured''s employee arising out of employment","Damage to a customer''s car caused by the insured''s delivery hand truck"]'::jsonb, 'Bodily injury to the insured''s employee arising out of employment', 'Employee injuries are excluded because workers compensation and employers liability cover them. Other exclusions include expected or intended injury, pollution, autos, and liquor liability for businesses selling alcohol.', 'Employees = workers comp, not CGL.', null),
('commercial_liability', 'medium', 'Commercial crime: taking property from someone by force or threat of violence is:', '["Forgery","Theft","Robbery","Burglary"]'::jsonb, 'Robbery', 'Robbery involves violence or the threat of violence against a person. Burglary involves forcible entry with visible marks. Theft is any unlawful taking.', 'Robbery = person + force/threat.', null),
('commercial_liability', 'medium', 'Burglary generally requires:', '["Taking property by threat of violence","Forcible entry into or exit from the premises, with visible marks","Any disappearance of property","An employee acting dishonestly"]'::jsonb, 'Forcible entry into or exit from the premises, with visible marks', 'Burglary is taking property from inside the premises by someone who unlawfully entered or exited by force, as shown by visible marks.', 'Burglary = forced entry/exit with visible marks.', null),
('commercial_liability', 'medium', 'Which commercial crime insuring agreement covers loss of money stolen by a bookkeeper?', '["Computer fraud","Money orders and counterfeit money","Forgery or alteration","Employee theft"]'::jsonb, 'Employee theft', 'Employee theft covers theft of money, securities, and other property by employees, acting alone or in collusion with others.', 'Dishonest employee = employee theft.', null),
('commercial_liability', 'hard', 'Under a discovery-form commercial crime policy, coverage applies to loss:', '["Sustained during the policy period and discovered within one year","Only if the employee is convicted","Discovered during the policy period, even if it occurred earlier (subject to any retroactive date)","Only if it occurs and is discovered on the same day"]'::jsonb, 'Discovered during the policy period, even if it occurred earlier (subject to any retroactive date)', 'The discovery form covers loss discovered during the policy period or the extended period. The loss sustained form covers loss that occurred during the policy period and is discovered within the discovery period after it ends.', 'Discovery form = discovered during the policy period.', null),
('commercial_liability', 'medium', 'The farm liability coverage form includes which coverage letters?', '["Coverage E – Liability and F – Medical payments","Coverage D – Loss of use","Coverage H – BI/PD, I – Personal and advertising injury, J – Medical payments","Coverage A – BI/PD, B – Personal and advertising injury, C – Medical payments"]'::jsonb, 'Coverage H – BI/PD, I – Personal and advertising injury, J – Medical payments', 'The farm liability form uses Coverage H (BI and PD), I (personal and advertising injury), and J (medical payments).', 'Farm liability = H, I, J.', null),
('commercial_liability', 'medium', 'A business that is sued for pollution from its premises is most likely to need coverage from:', '["A separate pollution liability coverage form","CGL Coverage C","The standard CGL Coverage A","The commercial property form"]'::jsonb, 'A separate pollution liability coverage form', 'The standard CGL has a broad pollution exclusion. Pollution liability coverage forms are used to cover these exposures.', 'Pollution = separate pollution liability form.', null),
('businessowners_liability', 'medium', 'The businessowners policy (BOP) Section II provides:', '["Building and business personal property","Business liability and medical expenses","Common policy conditions","Worker''s compensation"]'::jsonb, 'Business liability and medical expenses', 'BOP Section I is property, Section II is liability (including medical expenses), and Section III is common policy conditions.', 'BOP: I = property, II = liability, III = conditions.', null),
('businessowners_liability', 'medium', 'BOP Section II business liability combines coverage for:', '["Only bodily injury","Employee injuries","Only property damage to the insured''s building","Bodily injury, property damage, and personal and advertising injury"]'::jsonb, 'Bodily injury, property damage, and personal and advertising injury', 'BOP business liability covers BI, PD, and personal and advertising injury under one liability coverage, similar to CGL Coverages A and B.', 'BOP liability = BI + PD + P&AI.', null),
('businessowners_liability', 'medium', 'Which endorsement adds liability coverage for rented and employee-owned autos used for a BOP insured''s business?', '["Utility services – time element (BP 04 57)","Protective safeguards (BP 04 30)","Utility services – direct damage (BP 04 56)","Hired auto and non-owned auto liability (BP 04 04)"]'::jsonb, 'Hired auto and non-owned auto liability (BP 04 04)', 'BOP liability excludes autos. BP 04 04 adds hired and non-owned auto liability for businesses that do not own autos.', 'BOP hired/non-owned auto = BP 04 04.', null),
('businessowners_liability', 'medium', 'Which exposure is excluded from BOP business liability and should be insured elsewhere?', '["A customer slipping in the store","Advertising injury from a flyer","Professional services, such as medical or legal advice","Damage to a customer''s property caused by an employee on a job"]'::jsonb, 'Professional services, such as medical or legal advice', 'The BOP excludes professional services, autos, workers compensation, pollution, and liquor liability for businesses in the alcohol business, among others. Professional liability policies cover professional services.', 'Professional services need professional liability.', null),
('businessowners_liability', 'medium', 'BOP medical expenses coverage pays:', '["Medical expenses of others injured on the premises or from operations, regardless of fault","Employee medical bills","Only when the insured is legally liable","The owner''s medical bills"]'::jsonb, 'Medical expenses of others injured on the premises or from operations, regardless of fault', 'Like CGL Coverage C, BOP medical expenses pays regardless of fault and excludes insureds and employees.', 'BOP med pay = no-fault for the public.', null),
('businessowners_liability', 'medium', 'Under the BOP, who is an insured when the named insured is a corporation?', '["Only the officers","The corporation, plus its executive officers, directors, and stockholders for their duties or liability as such","Every customer of the corporation","Only the corporation"]'::jsonb, 'The corporation, plus its executive officers, directors, and stockholders for their duties or liability as such', 'Who is an insured depends on the business form. For a corporation, the organization is an insured, and officers, directors, and stockholders are insureds with respect to their duties or liability in those roles. Employees are insureds for acts within the scope of employment.', 'Corporation: the org + officers/directors/stockholders in their roles.', null),
('businessowners_liability', 'medium', 'BOP Section III common policy conditions include:', '["The liability limits","The property causes of loss","Worker''s compensation benefits","Cancellation, inspections and surveys, and premium payment rules that apply to the whole policy"]'::jsonb, 'Cancellation, inspections and surveys, and premium payment rules that apply to the whole policy', 'Section III contains conditions applying to both Sections I and II, such as cancellation, changes, examination of books and records, inspections, premiums, and transfer of rights.', 'Section III = conditions for the whole BOP.', null),
('businessowners_liability', 'hard', 'The BOP business liability limit applies:', '["Per occurrence, with separate aggregates for products-completed operations and for all other covered claims","Only to property in the insured''s care","As a single annual limit with no per-occurrence cap","Only to medical expenses"]'::jsonb, 'Per occurrence, with separate aggregates for products-completed operations and for all other covered claims', 'BOP liability has a per-occurrence limit and aggregate limits, including a separate products-completed operations aggregate, similar to the CGL.', 'BOP liability: per occurrence + aggregates.', null),
('businessowners_liability', 'medium', 'Who typically qualifies for a businessowners policy?', '["Small to mid-sized businesses such as offices, apartments, and retail stores that meet size and class limits","Auto dealers","Large manufacturers","Banks and financial institutions only"]'::jsonb, 'Small to mid-sized businesses such as offices, apartments, and retail stores that meet size and class limits', 'The BOP is a package for eligible small to mid-sized businesses. Many high-hazard classes, such as auto repair and large manufacturing, are ineligible.', 'BOP = eligible small/mid-size businesses.', null),
('businessowners_liability', 'medium', 'Damage a BOP insured''s employee causes to a customer''s floor while installing equipment is covered under:', '["Section III – Common policy conditions","Section I – Property","Worker''s compensation","Section II – Business liability"]'::jsonb, 'Section II – Business liability', 'Damage to others'' property caused by the insured''s operations is a liability loss under Section II.', 'Damage to others'' property = liability.', null),
('businessowners_liability', 'medium', 'Which statement about liquor liability under the BOP is correct?', '["It is always covered","It is excluded for all insureds, including those hosting an office party","It is excluded for insureds in the business of making, selling, or serving alcohol","It is covered under Section I"]'::jsonb, 'It is excluded for insureds in the business of making, selling, or serving alcohol', 'The liquor liability exclusion applies to insureds in the business of manufacturing, distributing, selling, serving, or furnishing alcohol. Host liquor liability for other businesses remains covered.', 'Selling alcohol = need liquor liability coverage.', null),
('businessowners_liability', 'hard', 'A small restaurant''s BOP liability would NOT cover which claim?', '["A diner who trips on a torn rug","A diner hit by an employee who was driving the restaurant''s delivery van","A diner who gets food poisoning","A diner whose coat is ruined by a waiter spilling soup"]'::jsonb, 'A diner hit by an employee who was driving the restaurant''s delivery van', 'Auto liability is excluded from the BOP. The restaurant needs a business auto policy for owned autos.', 'Owned autos = business auto policy, not BOP.', null),
('commercial_property', 'medium', 'A commercial package policy (CPP) is formed by combining:', '["Common policy declarations and conditions, interline endorsements, and two or more coverage parts","Any two homeowners forms","Only commercial property and inland marine","A BOP and a PAP"]'::jsonb, 'Common policy declarations and conditions, interline endorsements, and two or more coverage parts', 'A CPP is built from common declarations and conditions plus at least two coverage parts, such as commercial property and commercial general liability.', 'CPP = common pieces + 2 or more coverage parts.', null),
('commercial_property', 'medium', 'Which causes of loss form provides open perils coverage for commercial property?', '["Broad form","Special form","Basic form","Named form"]'::jsonb, 'Special form', 'Commercial property causes of loss forms: basic (named perils), broad (more named perils), and special (open perils subject to exclusions).', 'Special = open perils.', null),
('commercial_property', 'hard', 'Under the commercial property building and personal property form, if a building has been vacant more than 60 consecutive days, which applies?', '["Only fire is covered","Coverage continues unchanged","No coverage for vandalism, sprinkler leakage, glass breakage, water damage, theft, and attempted theft; other covered losses are reduced by 15%","All coverage is suspended"]'::jsonb, 'No coverage for vandalism, sprinkler leakage, glass breakage, water damage, theft, and attempted theft; other covered losses are reduced by 15%', 'The vacancy condition eliminates coverage for specified perils and reduces payment for other covered losses by 15% once the building has been vacant more than 60 consecutive days.', 'Vacant 60+ days: specified perils excluded, other losses −15%.', null),
('commercial_property', 'medium', 'Business income coverage pays:', '["Employee injuries","The cost to rebuild the building","Net income that would have been earned plus continuing normal operating expenses during the period of restoration","Liability claims from customers"]'::jsonb, 'Net income that would have been earned plus continuing normal operating expenses during the period of restoration', 'Business income replaces lost net income and continuing expenses, including payroll, while the business is suspended because of direct physical loss from a covered cause.', 'Lost net income + continuing expenses.', null),
('commercial_property', 'medium', 'Extra expense coverage pays:', '["Liability defense costs","Necessary costs above normal operating expenses to avoid or minimize a suspension of operations","Replacement of the building","The insured''s lost profits only"]'::jsonb, 'Necessary costs above normal operating expenses to avoid or minimize a suspension of operations', 'Extra expense pays additional costs, such as renting temporary space or expediting, to keep operating after a covered loss.', 'Extra costs to keep operating = extra expense.', null),
('commercial_property', 'medium', 'A contractor needs property coverage for a building while it is being constructed. The right coverage form is:', '["Equipment breakdown","Condominium association","Builders risk","Business income"]'::jsonb, 'Builders risk', 'The builders risk form covers buildings under construction, including materials and supplies at the site intended to become part of the building.', 'Building under construction = builders risk.', null),
('commercial_property', 'hard', 'The ordinance or law endorsement (CP 04 05) covers:', '["Liability for violating zoning laws","Fines for code violations","Flood damage","Loss to the undamaged part of a building, demolition cost, and increased cost of construction required by building codes"]'::jsonb, 'Loss to the undamaged part of a building, demolition cost, and increased cost of construction required by building codes', 'Building codes can require demolition of undamaged parts and upgraded construction. Standard forms exclude most of those costs; CP 04 05 adds coverage.', 'Code-required upgrades/demolition = CP 04 05.', null),
('commercial_property', 'medium', 'A retailer''s inventory swells before the holidays. Which endorsement increases the business personal property limit for that season?', '["Ordinance or law (CP 04 05)","Spoilage (CP 04 40)","Peak season limit of insurance (CP 12 30)","Value reporting form (CP 13 10)"]'::jsonb, 'Peak season limit of insurance (CP 12 30)', 'Peak season increases the business personal property limit for specified periods when inventory is higher.', 'Seasonal inventory = peak season.', null),
('commercial_property', 'medium', 'A grocery store''s frozen food spoils after a power outage. Which endorsement covers this?', '["Builders risk","Business income","Spoilage (CP 04 40)","Peak season (CP 12 30)"]'::jsonb, 'Spoilage (CP 04 40)', 'The spoilage endorsement covers perishable stock damaged by power outage, mechanical breakdown, or contamination from refrigeration failure.', 'Spoiled perishables = CP 04 40.', null),
('commercial_property', 'medium', 'A business whose inventory values fluctuate widely reports values monthly and pays premium based on actual values. It is using:', '["Agreed value","Peak season (CP 12 30)","Blanket insurance","Value reporting form (CP 13 10)"]'::jsonb, 'Value reporting form (CP 13 10)', 'The value reporting form lets the insured report values periodically, with premium adjusted to actual values. Late or inaccurate reports carry penalties.', 'Fluctuating values reported periodically = value reporting.', null),
('commercial_property', 'medium', 'Inland marine insurance generally covers:', '["Property that moves or is in transit, and property used in transportation and communication","Only ocean cargo","Buildings at a fixed location","Liability for auto accidents"]'::jsonb, 'Property that moves or is in transit, and property used in transportation and communication', 'The Nationwide Marine Definition classifies property that is movable, in transit, or an instrumentality of transportation or communication (bridges, towers) as inland marine.', 'Movable property = inland marine.', null),
('commercial_property', 'medium', 'A dry cleaner wants coverage for customers'' clothing in its possession, regardless of fault. The best coverage is:', '["Accounts receivable coverage","Signs coverage","Valuable papers coverage","Bailee''s customer coverage"]'::jsonb, 'Bailee''s customer coverage', 'Bailee''s customer coverage protects customers'' property in the bailee''s care, whether or not the bailee is legally liable.', 'Customers'' goods in your care = bailee''s customer.', null),
('commercial_property', 'medium', 'A contractor''s bulldozer and backhoes that move between job sites are best insured under:', '["Worker''s compensation","Business auto policy","Contractors equipment floater","Building and personal property form"]'::jsonb, 'Contractors equipment floater', 'The contractors equipment floater is an inland marine form covering mobile construction equipment wherever it is located.', 'Mobile construction equipment = contractors equipment floater.', null),
('commercial_property', 'medium', 'Equipment breakdown coverage (EB 00 20) protects against:', '["Sudden mechanical or electrical breakdown of equipment such as boilers and HVAC systems","Flood damage to equipment","Employee injuries caused by equipment","Theft of equipment"]'::jsonb, 'Sudden mechanical or electrical breakdown of equipment such as boilers and HVAC systems', 'Commercial property forms exclude mechanical and electrical breakdown. Equipment breakdown coverage fills that gap, often including resulting business income.', 'Mechanical/electrical breakdown = equipment breakdown.', null),
('businessowners_property', 'medium', 'BOP Section I property covers:', '["Employee injuries","Liability for customer injuries","Buildings and business personal property","Owned autos"]'::jsonb, 'Buildings and business personal property', 'BOP Section I covers buildings and business personal property, plus additional coverages such as business income and extra expense.', 'BOP Section I = buildings + BPP.', null),
('businessowners_property', 'medium', 'BOP property losses to buildings are generally settled on what basis?', '["Replacement cost","Actual cash value only","Agreed value only","Market value"]'::jsonb, 'Replacement cost', 'The BOP generally settles covered property losses at replacement cost, with no coinsurance clause.', 'BOP = replacement cost, no coinsurance.', null),
('businessowners_property', 'medium', 'Which statement about coinsurance in the BOP is correct?', '["The BOP does not use a coinsurance clause","The BOP uses 90% coinsurance on buildings","The BOP requires 80% coinsurance","The BOP requires 100% coinsurance"]'::jsonb, 'The BOP does not use a coinsurance clause', 'The BOP does not include coinsurance, though insurers expect insurance to value when setting limits.', 'No coinsurance in the BOP.', null),
('businessowners_property', 'hard', 'BOP business income coverage generally pays actual loss sustained for up to:', '["The Building limit only","12 consecutive months, without a separate dollar limit","30 days","A $10,000 limit"]'::jsonb, '12 consecutive months, without a separate dollar limit', 'BOP business income and extra expense pays actual loss sustained for up to 12 consecutive months after the physical loss, without a separate dollar limit.', 'BOP business income: 12 months, no dollar limit.', null),
('businessowners_property', 'hard', 'BOP business income coverage generally begins after a waiting period of:', '["24 hours","No waiting period","72 hours","7 days"]'::jsonb, '72 hours', 'Business income under the BOP generally begins 72 hours after the direct physical loss. Extra expense has no waiting period.', 'BOP business income: 72-hour wait.', null),
('businessowners_property', 'medium', 'A BOP insured gets a premium credit for having a sprinkler system. The endorsement that makes maintaining it a condition of coverage is:', '["Hired and non-owned auto (BP 04 04)","Protective safeguards (BP 04 30)","Utility services – time element (BP 04 57)","Utility services – direct damage (BP 04 56)"]'::jsonb, 'Protective safeguards (BP 04 30)', 'Protective safeguards requires the insured to maintain listed safeguards, such as sprinklers or alarms. Failure to do so can suspend coverage for fire losses.', 'Maintain sprinklers/alarms = BP 04 30.', null),
('businessowners_property', 'medium', 'A power failure at the utility''s off-site plant damages food in a BOP insured''s freezer. Which endorsement covers the direct damage?', '["Utility services – direct damage (BP 04 56)","Utility services – time element (BP 04 57)","Hired and non-owned auto (BP 04 04)","Protective safeguards (BP 04 30)"]'::jsonb, 'Utility services – direct damage (BP 04 56)', 'Utility services – direct damage covers physical damage from interruption of off-premises utility service. The time element version covers the resulting lost income.', 'Off-site utility interruption: BP 04 56 (damage), BP 04 57 (income).', null),
('businessowners_property', 'medium', 'A BOP insured loses income because an off-premises utility outage forced it to close. Which endorsement covers the lost income?', '["Utility services – direct damage (BP 04 56)","Spoilage (CP 04 40)","Utility services – time element (BP 04 57)","Protective safeguards (BP 04 30)"]'::jsonb, 'Utility services – time element (BP 04 57)', 'Time element coverages address lost income and extra expense. BP 04 57 extends business income to off-premises utility interruptions.', 'Lost income from utility outage = BP 04 57.', null),
('businessowners_property', 'medium', 'Which is an optional coverage available in the BOP Section I?', '["Outdoor signs, money and securities, and employee dishonesty","Professional liability","Owned auto physical damage","Worker''s compensation"]'::jsonb, 'Outdoor signs, money and securities, and employee dishonesty', 'BOP optional property coverages include outdoor signs, money and securities, employee dishonesty, and equipment breakdown (in many versions).', 'BOP options: signs, money & securities, employee dishonesty.', null),
('businessowners_property', 'medium', 'The BOP property deductible generally applies:', '["Only to liability claims","Per occurrence to property losses","Only to theft","Per item"]'::jsonb, 'Per occurrence to property losses', 'The standard BOP deductible applies per occurrence to Section I losses. Some additional coverages have no deductible.', 'BOP deductible = per occurrence, property.', null),
('businessowners_property', 'hard', 'Under the BOP, the business personal property limit may automatically increase by 25% when:', '["The building is vacant","The insured adds a new location","The insured''s inventory rises seasonally, if the limit equals at least 100% of the average monthly values for the prior 12 months","A flood occurs"]'::jsonb, 'The insured''s inventory rises seasonally, if the limit equals at least 100% of the average monthly values for the prior 12 months', 'The BOP''s seasonal increase raises the business personal property limit by 25% to cover peaks, provided the limit is at least 100% of average monthly values over the prior 12 months.', 'BOP seasonal increase = 25%.', null),
('businessowners_property', 'medium', 'A BOP insured must continue paying employees while the building is repaired after a fire. That payroll is covered under:', '["Liability coverage","Building coverage","Extra expense only","Business income (as a continuing normal operating expense)"]'::jsonb, 'Business income (as a continuing normal operating expense)', 'Business income includes continuing normal operating expenses, including payroll, during the period of restoration.', 'Continuing payroll = business income.', null),
('workers_comp', 'medium', 'The exclusive remedy doctrine means that injured employees generally:', '["Cannot sue their employer for work injuries covered by worker''s compensation","May sue their employer and collect worker''s compensation","Must sue the employer before receiving benefits","Can collect only if the employer was negligent"]'::jsonb, 'Cannot sue their employer for work injuries covered by worker''s compensation', 'Worker''s compensation is a no-fault system. In exchange for guaranteed benefits, employees generally give up the right to sue the employer.', 'Comp benefits instead of suing the employer.', null),
('workers_comp', 'medium', 'Under Wisconsin law, an employer must carry worker''s compensation insurance if it:', '["Is incorporated","Employs 3 or more full- or part-time workers","Has annual revenue over $1 million","Has any employee working more than 40 hours a week"]'::jsonb, 'Employs 3 or more full- or part-time workers', 'Wisconsin''s DWD: employers with 3 or more full- or part-time workers must be insured. Employers with 1 or more workers who pay $500 or more in wages in a calendar quarter must also insure.', 'WI: 3+ employees, or $500+ wages in a quarter.', 'Wisconsin'),
('workers_comp', 'hard', 'A Wisconsin employer with one employee pays that employee $500 or more in wages in a calendar quarter. The employer must:', '["Carry worker''s compensation insurance, starting by the 10th day of the first month of the next quarter","Buy coverage only if the employee requests it","Do nothing until it has 3 employees","Self-insure only"]'::jsonb, 'Carry worker''s compensation insurance, starting by the 10th day of the first month of the next quarter', 'DWD guidance: employers who pay $500 or more in wages in any calendar quarter must have coverage by the 10th day of the first month of the next quarter.', '$500 in a quarter → insure by the 10th of next quarter''s first month.', 'Wisconsin'),
('workers_comp', 'hard', 'A Wisconsin farmer must carry worker''s compensation insurance if the farmer employs:', '["1 or more workers at any time","Seasonal workers only","3 or more workers for one week","6 or more workers on any 20 days during a calendar year"]'::jsonb, '6 or more workers on any 20 days during a calendar year', 'Wisconsin farmers must be covered if they employ 6 or more workers on any 20 days during a calendar year.', 'WI farms: 6+ workers on any 20 days.', 'Wisconsin'),
('workers_comp', 'medium', 'Wisconsin is best described as what type of worker''s compensation state?', '["Competitive: employers buy from private insurers or, with approval, self-insure","Elective: employers may choose not to provide benefits at all","Monopolistic: only a state fund may write coverage","Federal: coverage is provided by the U.S. government"]'::jsonb, 'Competitive: employers buy from private insurers or, with approval, self-insure', 'Wisconsin employers buy from licensed insurers or get approval to self-insure. Monopolistic states require coverage through a state fund.', 'WI = competitive, with self-insurance allowed.', 'Wisconsin'),
('workers_comp', 'medium', 'The Wisconsin Uninsured Employers Fund:', '["Insures employers rejected by private insurers","Covers independent contractors","Pays benefits to employees injured while working for illegally uninsured employers","Pays for employer premium discounts"]'::jsonb, 'Pays benefits to employees injured while working for illegally uninsured employers', 'The UEF pays valid claims when the employer was illegally uninsured, and the employer must reimburse the UEF.', 'UEF = benefits when the employer illegally had no comp.', 'Wisconsin'),
('workers_comp', 'medium', 'A Wisconsin employer is rejected by private worker''s compensation insurers. Coverage can be obtained through:', '["The WAIP","The Uninsured Employers Fund","The Wisconsin Insurance Plan","An assignment through the Wisconsin Compensation Rating Bureau (the Wisconsin Worker''s Compensation Insurance Pool)"]'::jsonb, 'An assignment through the Wisconsin Compensation Rating Bureau (the Wisconsin Worker''s Compensation Insurance Pool)', 'DWD says the WCRB assigns coverage for employers who are denied, and the cost is the same as other coverage. The pool is the Wisconsin Worker''s Compensation Insurance Pool.', 'Rejected employers → WCRB assignment (WWCIP).', 'Wisconsin'),
('workers_comp', 'medium', 'Part One of the worker''s compensation and employers liability policy pays:', '["Employer''s liability lawsuits","Premium audits","The benefits required by the state worker''s compensation law","Coverage for work in other states not listed"]'::jsonb, 'The benefits required by the state worker''s compensation law', 'Part One pays statutory benefits. Part Two covers employers liability lawsuits, and Part Three provides other states insurance.', 'Part One = statutory benefits. Part Two = employers liability.', null),
('workers_comp', 'hard', 'An employee''s spouse sues the employer for loss of consortium after a workplace injury. This claim falls under:', '["The CGL","Part Three – Other states insurance","Part Two – Employers liability","Part One – Worker''s compensation"]'::jsonb, 'Part Two – Employers liability', 'Employers liability covers suits not barred by exclusive remedy, such as third-party-over actions and consequential injury claims by family members, like loss of consortium.', 'Suits outside the comp system = employers liability.', null),
('workers_comp', 'medium', 'Worker''s compensation premiums are generally based on:', '["The employer''s gross sales","Payroll per $100, by job classification","A flat rate for all employers","Number of employees only"]'::jsonb, 'Payroll per $100, by job classification', 'Premium equals the rate per $100 of payroll for each classification, adjusted by experience modification and discounts. A final audit adjusts for actual payroll.', 'Premium = rate × payroll/100 by class.', null),
('workers_comp', 'medium', 'An employer with better-than-average loss experience for its size and class will usually have an experience modification factor:', '["Exactly 1.00","Above 1.00, increasing its premium","Below 1.00, reducing its premium","That does not affect its premium"]'::jsonb, 'Below 1.00, reducing its premium', 'An experience mod compares the employer''s losses with expected losses for similar employers. Below 1.00 is a credit; above 1.00 is a debit.', 'Mod under 1.00 = credit.', null),
('workers_comp', 'medium', 'Which organization collects data and administers worker''s compensation classifications and experience rating in Wisconsin?', '["The Wisconsin Compensation Rating Bureau (WCRB)","The Wisconsin Insurance Plan","The Department of Transportation","The Wisconsin Insurance Security Fund"]'::jsonb, 'The Wisconsin Compensation Rating Bureau (WCRB)', 'The WCRB is Wisconsin''s rating organization for worker''s compensation: classifications, experience rating, and assignment of coverage for rejected employers.', 'WI comp rating = WCRB.', 'Wisconsin'),
('umbrella', 'medium', 'A personal umbrella policy typically:', '["Replaces homeowners and auto liability entirely","Pays the insured''s own medical bills","Covers only property damage to the insured''s home","Provides excess liability above underlying policies and may cover some claims the underlying policies exclude"]'::jsonb, 'Provides excess liability above underlying policies and may cover some claims the underlying policies exclude', 'An umbrella sits above required underlying liability limits and may drop down to cover certain claims not covered by underlying policies, subject to a self-insured retention.', 'Umbrella = excess + some drop-down coverage.', null),
('umbrella', 'medium', 'When an umbrella covers a claim that no underlying policy covers, the insured usually pays:', '["A coinsurance penalty","Nothing at all","A self-insured retention","The full underlying limit"]'::jsonb, 'A self-insured retention', 'For claims covered by the umbrella but not by underlying insurance, the insured pays the self-insured retention before the umbrella responds.', 'Drop-down claims = insured pays the SIR.', null),
('umbrella', 'hard', 'An insured lets the required underlying auto liability coverage lapse, then causes a $400,000 accident. The umbrella generally:', '["Pays the full $400,000","Pays nothing, and cancels the policy retroactively","Pays only what it would have paid if the underlying coverage were in force","Pays the underlying limit only"]'::jsonb, 'Pays only what it would have paid if the underlying coverage were in force', 'Umbrellas require the insured to maintain underlying limits. If they are not maintained, the umbrella responds as if the underlying coverage applied, leaving the insured to pay that gap.', 'Keep underlying limits, or you pay the gap.', null),
('umbrella', 'medium', 'How does a true excess (following-form) liability policy differ from an umbrella?', '["An excess policy has no limit","An excess policy covers more claims than the underlying policy","An excess policy pays first","An excess policy follows the underlying terms and does not drop down to broaden coverage"]'::jsonb, 'An excess policy follows the underlying terms and does not drop down to broaden coverage', 'A following-form excess policy adds limits on the same terms as the underlying policy. An umbrella may also provide broader coverage.', 'Excess = more limits. Umbrella = more limits + broader coverage.', null),
('umbrella', 'medium', 'Umbrella policies generally treat defense costs:', '["As payable in addition to the umbrella limit in many forms, when the umbrella has the duty to defend","As a deductible","As never covered","As paid only by the insured"]'::jsonb, 'As payable in addition to the umbrella limit in many forms, when the umbrella has the duty to defend', 'When underlying limits are exhausted, or for drop-down claims, the umbrella insurer often assumes the duty to defend, and many forms pay defense costs in addition to limits.', 'Umbrella defends once underlying is exhausted.', null),
('umbrella', 'medium', 'A commercial umbrella usually requires underlying coverage for:', '["Crime and fidelity","Worker''s compensation Part One only","General liability, business auto liability, and employers liability","Commercial property and inland marine"]'::jsonb, 'General liability, business auto liability, and employers liability', 'Commercial umbrellas require scheduled underlying liability coverages, commonly CGL, business auto, and employers liability.', 'Commercial umbrella sits over CGL, auto, and EL.', null),
('casualty_other', 'medium', 'Errors and omissions insurance protects:', '["Professionals against claims of negligent acts, errors, or omissions in their professional services","Businesses against property damage","Customers against product defects","Employees against workplace injuries"]'::jsonb, 'Professionals against claims of negligent acts, errors, or omissions in their professional services', 'E&O (professional liability) covers claims arising from mistakes in professional services, which the CGL excludes. Insurance producers commonly carry E&O.', 'Professional mistakes = E&O.', null),
('casualty_other', 'medium', 'Employment practices liability insurance (EPLI) covers claims of:', '["Damage to employee-owned cars","Theft by employees","Wrongful termination, discrimination, and harassment","Employee injuries on the job"]'::jsonb, 'Wrongful termination, discrimination, and harassment', 'EPLI covers employment-related claims. Worker''s compensation covers work injuries, and crime coverage handles employee theft.', 'Firing/discrimination/harassment claims = EPLI.', null),
('casualty_other', 'medium', 'A bar that serves alcohol needs which coverage to protect against claims from a drunk patron''s car accident?', '["Commercial property","Liquor liability","Crime","Inland marine"]'::jsonb, 'Liquor liability', 'The CGL excludes liquor liability for businesses that sell or serve alcohol. A separate liquor liability policy fills this gap.', 'Selling alcohol = liquor liability policy.', null),
('casualty_other', 'medium', 'The three parties to a surety bond are:', '["Owner, tenant, and lender","Principal, obligee, and surety","Employer, employee, and insurer","Insured, insurer, and producer"]'::jsonb, 'Principal, obligee, and surety', 'The principal promises to perform, the obligee is protected, and the surety guarantees the principal''s performance.', 'Principal promises, obligee is protected, surety guarantees.', null),
('casualty_other', 'hard', 'How does a surety bond differ from insurance?', '["The obligee pays the premium and is the insured","The surety expects no losses and can recover payments from the principal","The surety pools premiums to pay expected losses","Surety bonds cover only property losses"]'::jsonb, 'The surety expects no losses and can recover payments from the principal', 'Surety is credit-based. The surety expects the principal to perform, and if it pays the obligee, the principal must indemnify the surety.', 'Surety pays, then collects from the principal.', null),
('casualty_other', 'medium', 'A contractor must guarantee that it will complete a construction project according to contract. Which bond is required?', '["Performance bond","License and permit bond","Fiduciary bond","Public official bond"]'::jsonb, 'Performance bond', 'Contract bonds include bid, performance, and payment bonds. A performance bond guarantees the contractor will complete the work as agreed.', 'Finish the job as promised = performance bond.', null),
('casualty_other', 'medium', 'A court requires a person appointed to manage an estate to post a bond guaranteeing faithful performance. This is a:', '["Bid bond","Payment bond","Fiduciary bond","License bond"]'::jsonb, 'Fiduciary bond', 'Fiduciary (probate) bonds are court bonds guaranteeing that executors, administrators, guardians, and trustees faithfully perform their duties.', 'Estate managers = fiduciary bonds.', null),
('casualty_other', 'medium', 'Cyber (network security and privacy) liability coverage addresses:', '["Auto accidents","Employee theft of cash","Physical damage to computers from fire","Data breaches and network security failures, including notification costs and resulting liability"]'::jsonb, 'Data breaches and network security failures, including notification costs and resulting liability', 'Cyber liability covers the costs and liability from data breaches and network security incidents, which traditional property and liability forms generally exclude.', 'Data breach = cyber liability.', null)
) as v(domain, difficulty, question, options, correct, explanation, know_this, state_specific)
where not exists (
  select 1 from public.questions existing where existing.question = v.question
);
